@property --mco-quick-g { syntax: "<color>"; inherits: true; initial-value: oklch(0.86 0.045 82); }
@keyframes mco-quick-in { from { opacity: 0; translate: 0 10px; scale: .94; } }
@keyframes mco-quick-pop { from { scale: .3; opacity: 0; } }
@keyframes mco-quick-spin { to { rotate: 360deg; } }
@keyframes mco-quick-pulse { 50% { opacity: .35; } }

.mco-quick {
  /* re-theme with these four; --mco-quick-g is the garment colour, set per swatch */
  --mco-quick-bg: oklch(0.972 0.013 84);
  --mco-quick-ink: oklch(0.25 0.02 55);
  --mco-quick-accent: oklch(0.55 0.16 36);
  --mco-quick-ok: oklch(0.5 0.11 152);

  --mco-quick-muted: color-mix(in oklch, var(--mco-quick-ink) 58%, var(--mco-quick-bg));
  --mco-quick-line: color-mix(in oklch, var(--mco-quick-ink) 14%, transparent);
  --mco-quick-shade: oklch(0.2 0.03 60 / .55);
  --mco-quick-spring: linear(0, 0.009, 0.035 2.1%, 0.141 4.4%, 0.723 12.9%, 0.938 16.7%, 1.017 19.4%, 1.067, 1.099 24.3%, 1.104 26.4%, 1.098 28.7%, 1.045 34.9%, 1.009 41.2%, 0.993 47.6%, 0.995 59.1%, 1);
  --mco-quick-out: cubic-bezier(.2, .9, .1, 1);

  container-type: inline-size;
  position: relative; box-sizing: border-box;
  width: 100%; max-width: 420px; min-height: 158px;
  display: grid; grid-template-areas: "top" "media" "info"; gap: 8px;
  padding: 10px 10px 14px;
  border-radius: 18px;
  background: var(--mco-quick-bg); color: var(--mco-quick-ink);
  font: 14px/1.4 system-ui, -apple-system, "Segoe UI", sans-serif;
  -webkit-font-smoothing: antialiased;
  box-shadow: 0 1px 0 oklch(1 0 0 / .7) inset, 0 22px 44px -28px var(--mco-quick-shade);
  transition: --mco-quick-g .7s var(--mco-quick-out);

  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(button) { font: inherit; color: inherit; background: none; border: 0; padding: 0; margin: 0; cursor: pointer; -webkit-tap-highlight-color: transparent; }
  & :where(svg) { display: block; fill: none; stroke: currentColor; stroke-width: 1.5; stroke-linecap: round; stroke-linejoin: round; }
  & :where(p, h3) { margin: 0; }
  & :focus-visible { outline: 2px solid var(--mco-quick-accent); outline-offset: 2px; }
  & .mco-quick-sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }

  /* ---------- header ---------- */
  & .mco-quick-top { grid-area: top; display: flex; align-items: center; justify-content: space-between; padding: 0 4px; }
  & .mco-quick-brand { font-size: 11px; font-weight: 700; letter-spacing: .14em; text-transform: uppercase; }
  & .mco-quick-crumb { font-weight: 500; letter-spacing: .06em; color: var(--mco-quick-muted); }
  & .mco-quick-bag {
    display: inline-flex; align-items: center; gap: 5px;
    height: 28px; padding: 0 10px 0 8px; border-radius: 14px;
    background: color-mix(in oklch, var(--mco-quick-ink) 6%, transparent);
    font-size: 12px; font-weight: 650; font-variant-numeric: tabular-nums;
    transition: background-color .3s, color .3s;
    & svg { width: 17px; height: 17px; }
  }
  &[data-count] .mco-quick-bag { background: var(--mco-quick-ink); color: var(--mco-quick-bg); }

  /* ---------- media ---------- */
  & .mco-quick-media {
    grid-area: media; position: relative;
    aspect-ratio: 6 / 5; border-radius: 13px; overflow: hidden;
    display: grid; place-items: center;
    background:
      radial-gradient(70% 60% at 50% 38%, oklch(1 0 0 / .55), transparent 70%),
      color-mix(in oklch, var(--mco-quick-g) 24%, var(--mco-quick-bg));
  }
  & .mco-quick-flag {
    position: absolute; top: 10px; left: 10px; z-index: 1;
    padding: 4px 8px; border-radius: 6px;
    background: var(--mco-quick-bg);
    font-size: 10px; font-weight: 700; letter-spacing: .12em; text-transform: uppercase;
  }
  & .mco-quick-art { width: min(84%, 300px); height: auto; margin-top: -6%; overflow: visible; }
  & .mco-quick-garment { transition: translate .6s var(--mco-quick-spring); }
  & .mco-quick-media:hover .mco-quick-garment { translate: 0 -4px; }
  & .mco-quick-art :where(path, ellipse) { stroke: none; }
  & .mco-quick-shadow { fill: oklch(0.3 0.03 60 / .32); filter: blur(4px); transition: scale .6s var(--mco-quick-spring); transform-origin: 120px 186px; }
  & .mco-quick-media:hover .mco-quick-shadow { scale: .9; }
  & .mco-quick-body { fill: var(--mco-quick-g); stroke: color-mix(in oklch, var(--mco-quick-g) 70%, black); stroke-width: 1.2; }
  & .mco-quick-rib { fill: color-mix(in oklch, var(--mco-quick-g) 86%, black); }
  & .mco-quick-neckin { fill: color-mix(in oklch, var(--mco-quick-g) 62%, black); }
  & .mco-quick-lines, & .mco-quick-fold, & .mco-quick-collar { fill: none; }
  & .mco-quick-lines { stroke: color-mix(in oklch, var(--mco-quick-g) 70%, black); stroke-width: 1.4; }
  & .mco-quick-fold { stroke: color-mix(in oklch, var(--mco-quick-g) 80%, black); stroke-width: 1.4; opacity: .55; }
  & .mco-quick-collar { stroke: color-mix(in oklch, var(--mco-quick-g) 80%, black); stroke-width: 6; }

  /* ---------- tray: panel shares a cell with the pill, clipped to the pill's rect until open ---------- */
  & .mco-quick-tray {
    position: absolute; inset: auto 10px 10px 10px;
    display: grid; justify-items: end; align-items: end;
    & > * { grid-area: 1 / 1; }
  }
  & .mco-quick-open {
    width: 122px; height: 38px; border-radius: 19px;
    display: inline-flex; align-items: center; justify-content: center; gap: 7px;
    background: var(--mco-quick-ink); color: var(--mco-quick-bg);
    font-size: 13px; font-weight: 650; letter-spacing: .01em;
    box-shadow: 0 8px 18px -8px var(--mco-quick-shade);
    transition: translate .45s var(--mco-quick-spring), scale .45s var(--mco-quick-spring), opacity .2s, background-color .25s;
    & svg { width: 15px; height: 15px; stroke-width: 1.8; }
    & .mco-quick-tick { display: none; }
    &:hover { translate: 0 -2px; background: color-mix(in oklch, var(--mco-quick-ink) 82%, var(--mco-quick-accent)); }
    &:active { scale: .96; }
    &[data-done] { background: var(--mco-quick-ok);
      & .mco-quick-plus { display: none; }
      & .mco-quick-tick { display: block; animation: mco-quick-pop .5s var(--mco-quick-spring) both; }
    }
  }
  &[data-open] .mco-quick-open { opacity: 0; scale: .92; visibility: hidden; transition: opacity .15s, scale .3s, visibility 0s .15s; }

  & .mco-quick-panel {
    justify-self: stretch;
    padding: 9px 9px 7px; border-radius: 15px;
    background: var(--mco-quick-bg);
    box-shadow: 0 14px 30px -14px var(--mco-quick-shade);
    clip-path: inset(calc(100% - 38px) 0 0 calc(100% - 122px) round 19px);
    visibility: hidden;
    transition: clip-path .42s var(--mco-quick-out), visibility 0s .42s;
  }
  &[data-open] .mco-quick-panel { clip-path: inset(0 round 15px); visibility: visible; transition: clip-path .55s var(--mco-quick-out), visibility 0s; }
  & .mco-quick-phead {
    display: flex; align-items: center; justify-content: space-between;
    padding: 0 1px 7px 3px;
    font-size: 11px; font-weight: 600; letter-spacing: .1em; text-transform: uppercase; color: var(--mco-quick-muted);
    & b { color: var(--mco-quick-ink); font-weight: 700; }
  }
  & .mco-quick-x {
    width: 26px; height: 26px; border-radius: 8px; display: grid; place-items: center;
    & svg { width: 14px; height: 14px; }
    &:hover { background: color-mix(in oklch, var(--mco-quick-ink) 8%, transparent); }
  }
  & .mco-quick-sizes { display: grid; grid-template-columns: repeat(5, 1fr); gap: 5px; }
  & .mco-quick-size {
    position: relative; height: 44px; border-radius: 10px;
    display: grid; place-content: center; justify-items: center;
    border: 1px solid var(--mco-quick-line);
    font-weight: 650; font-size: 13.5px; font-variant-numeric: tabular-nums;
    transition: border-color .2s, background-color .2s, translate .35s var(--mco-quick-spring), scale .35s var(--mco-quick-spring), opacity .2s;
    & small { font-size: 9.5px; font-weight: 600; line-height: 1.1; color: var(--mco-quick-accent); }
    & small:empty { display: none; }
    &:hover { border-color: var(--mco-quick-ink); translate: 0 -1px; }
    &:active { scale: .95; }
    &[data-out] {
      color: var(--mco-quick-muted); cursor: not-allowed;
      background: linear-gradient(to top right, transparent calc(50% - .6px), var(--mco-quick-line) calc(50% - .6px) calc(50% + .6px), transparent calc(50% + .6px));
      & small { color: var(--mco-quick-muted); }
      &:hover { translate: none; border-color: var(--mco-quick-line); }
    }
    &[data-busy] { color: transparent; border-color: var(--mco-quick-ink);
      & small { color: transparent; }
      &::after {
        content: ""; position: absolute; inset: 0; margin: auto; width: 16px; height: 16px; border-radius: 50%;
        border: 2px solid color-mix(in oklch, var(--mco-quick-ink) 18%, transparent); border-top-color: var(--mco-quick-ink);
        animation: mco-quick-spin .7s linear infinite;
      }
    }
  }
  &[data-busy] .mco-quick-size:not([data-busy]) { opacity: .4; pointer-events: none; }
  &[data-open] .mco-quick-size { animation: mco-quick-in .5s var(--mco-quick-spring) both; animation-delay: calc(var(--i) * 38ms + 110ms); }

  & .mco-quick-msg {
    margin: 7px 2px 0; min-height: 17px;
    display: flex; align-items: center; flex-wrap: wrap; gap: 4px 6px;
    font-size: 11.5px; line-height: 1.35; color: var(--mco-quick-muted); text-wrap: pretty;
    & svg { width: 14px; height: 14px; flex: none; padding: 2px; border-radius: 50%; background: var(--mco-quick-ok); color: var(--mco-quick-bg); stroke-width: 2.4; animation: mco-quick-pop .45s var(--mco-quick-spring) both; }
    &[data-tone="ok"] { color: var(--mco-quick-ok); font-weight: 600; }
    &[data-tone="err"] { color: var(--mco-quick-accent); font-weight: 600; }
    &[data-tone="warn"] { color: var(--mco-quick-ink); }
  }
  & .mco-quick-notify {
    font-weight: 700; text-decoration: underline; text-underline-offset: 3px; text-decoration-color: var(--mco-quick-accent);
    &:disabled { cursor: default; text-decoration: none; color: var(--mco-quick-muted); }
  }

  /* ---------- info ---------- */
  & .mco-quick-info {
    grid-area: info; display: grid;
    grid-template-columns: 1fr auto; grid-template-areas: "name price" "rate rate" "col col";
    align-items: baseline; gap: 2px 10px; padding: 4px 4px 0;
  }
  & .mco-quick-name { grid-area: name; font-size: clamp(15px, 5.2cqi, 19px); font-weight: 650; letter-spacing: -.01em; line-height: 1.2; text-wrap: balance; }
  & .mco-quick-price {
    grid-area: price; text-align: right;
    display: flex; align-items: baseline; justify-content: flex-end; flex-wrap: wrap; gap: 0 6px;
    font-variant-numeric: tabular-nums; font-size: clamp(14px, 4.6cqi, 17px);
    & s { color: var(--mco-quick-muted); font-size: .82em; }
  }
  & .mco-quick-now { font-weight: 700; }
  & .mco-quick-off { font-size: 10.5px; font-weight: 750; letter-spacing: .04em; color: var(--mco-quick-bg); background: var(--mco-quick-accent); padding: 1px 5px; border-radius: 5px; }
  & .mco-quick-rate { grid-area: rate; display: flex; align-items: center; gap: 6px; font-size: 12px; font-variant-numeric: tabular-nums; }
  & .mco-quick-dim { color: var(--mco-quick-muted); }
  & .mco-quick-stars {
    position: relative; display: block; width: 66px; height: 13px;
    & svg { position: absolute; inset: 0; width: 100%; height: 100%; stroke: none; fill: color-mix(in oklch, var(--mco-quick-ink) 16%, transparent); }
    & .mco-quick-starfill { fill: var(--mco-quick-ink); clip-path: inset(0 6% 0 0); }
  }
  & .mco-quick-colours { grid-area: col; display: flex; align-items: center; gap: 10px; margin-top: 8px; }
  & .mco-quick-sw {
    display: flex; gap: 8px;
    & [role="radio"] {
      width: 24px; height: 24px; border-radius: 50%; background: var(--sw);
      box-shadow: inset 0 0 0 1px oklch(0 0 0 / .14), 0 0 0 2px var(--mco-quick-bg), 0 0 0 2px transparent;
      transition: box-shadow .25s var(--mco-quick-out), scale .4s var(--mco-quick-spring);
      &:hover { scale: 1.1; }
      &[aria-checked="true"] { box-shadow: inset 0 0 0 1px oklch(0 0 0 / .14), 0 0 0 2.5px var(--mco-quick-bg), 0 0 0 4px var(--mco-quick-ink); }
      &:focus-visible { outline-offset: 5px; }
    }
  }
  & .mco-quick-cname { font-size: 12.5px; color: var(--mco-quick-muted); }
  & .mco-quick-colours:has([data-c="2"][aria-checked="true"]) .mco-quick-cname::after { content: " · Sale"; color: var(--mco-quick-accent); font-weight: 650; }

  & .mco-quick-dot {
    position: absolute; left: 0; top: 0; z-index: 5; pointer-events: none;
    width: 14px; height: 14px; margin: -7px 0 0 -7px; border-radius: 50%;
    background: var(--mco-quick-g);
    box-shadow: 0 0 0 2px var(--mco-quick-bg), 0 6px 14px -4px var(--mco-quick-shade);
  }

  @container (min-width: 520px) {
    grid-template-columns: 1.1fr 1fr; grid-template-rows: auto 1fr;
    grid-template-areas: "media top" "media info"; column-gap: 16px;
    & .mco-quick-top { padding-top: 4px; }
    & .mco-quick-info { align-content: start; }
  }
  @container (max-width: 290px) {
    & .mco-quick-crumb { display: none; }
    & .mco-quick-sizes { gap: 3px; }
    & .mco-quick-size { height: 42px; font-size: 12.5px; }
  }
}

@media (prefers-reduced-motion: reduce) {
  .mco-quick {
    transition: --mco-quick-g .2s linear;
    & .mco-quick-panel, &[data-open] .mco-quick-panel { clip-path: none; opacity: 0; transition: opacity .2s, visibility 0s .2s; }
    &[data-open] .mco-quick-panel { opacity: 1; transition: opacity .2s; }
    &[data-open] .mco-quick-size { animation: none; }
    & .mco-quick-garment, & .mco-quick-shadow, & .mco-quick-open, & .mco-quick-size, & .mco-quick-sw [role="radio"] { transition-duration: .01s; }
    & .mco-quick-media:hover .mco-quick-garment, & .mco-quick-open:hover, & .mco-quick-size:hover, & .mco-quick-sw [role="radio"]:hover { translate: none; scale: none; }
    & .mco-quick-size[data-busy]::after { animation: mco-quick-pulse 1.2s ease-in-out infinite; border-color: var(--mco-quick-ink); }
    & .mco-quick-open[data-done] .mco-quick-tick, & .mco-quick-msg svg { animation: none; }
  }
}

js:
const $ = (s) => root.querySelector(s);
const $$ = (s) => Array.from(root.querySelectorAll(s));
const reduce = matchMedia('(prefers-reduced-motion: reduce)');
const SIZES = ['XS', 'S', 'M', 'L', 'XL'];
const LIMIT = 2;
const COLOURS = [
  { name: 'Oat', g: 'oklch(0.86 0.045 82)', price: 120, stock: { XS: 4, S: 12, M: 9, L: 2, XL: 0 } },
  { name: 'Moss', g: 'oklch(0.56 0.085 135)', price: 120, stock: { XS: 0, S: 6, M: 14, L: 8, XL: 3 } },
  { name: 'Rust', g: 'oklch(0.57 0.14 42)', price: 90, was: 120, stock: { XS: 2, S: 5, M: 0, L: 7, XL: 1 } },
  { name: 'Charcoal', g: 'oklch(0.34 0.012 260)', price: 120, stock: { XS: 7, S: 11, M: 18, L: 12, XL: 6 } }
];
const TICK = '<svg viewBox="0 0 16 16" aria-hidden="true"><path d="M4 8.4l2.6 2.6L12 5.4"/></svg>';
const bag = {};
const notified = new Set();
let colour = 0, count = 0, busy = false, closeT = 0, doneT = 0;

const openBtn = $('[data-opener]'), openLabel = $('[data-openlabel]'), msg = $('[data-msg]');
const sizes = $$('.mco-quick-size'), swatches = $$('[data-sw] [role="radio"]');
const art = $('[data-art]'), bagEl = $('[data-bag]'), bagN = $('[data-bagn]'), bagLive = $('[data-baglive]');
const isOut = (b) => b.getAttribute('aria-disabled') === 'true';

function setMsg(text, tone, extra) {
  msg.dataset.tone = tone || '';
  msg.textContent = text;
  if (tone === 'ok') msg.insertAdjacentHTML('afterbegin', TICK);
  if (extra) msg.append(extra);
}
function idleMsg() {
  const st = COLOURS[colour].stock;
  const low = SIZES.filter((s) => st[s] > 0 && st[s] <= 3);
  setMsg(low.length ? 'Low stock in ' + low.join(', ') + ' · free 30-day returns' : 'Every size ships today · free 30-day returns');
}
function paintSizes() {
  const col = COLOURS[colour];
  sizes.forEach((b) => {
    const s = b.dataset.s, n = col.stock[s];
    b.toggleAttribute('data-out', n === 0);
    b.setAttribute('aria-disabled', n === 0 ? 'true' : 'false');
    b.querySelector('small').textContent = n === 0 ? 'Sold out' : n <= 3 ? n + ' left' : '';
    b.setAttribute('aria-label', s + ', ' + (n === 0 ? 'sold out' : n <= 3 ? 'only ' + n + ' left' : 'in stock'));
  });
}
function paintColour(animate) {
  const col = COLOURS[colour];
  root.style.setProperty('--mco-quick-g', col.g);
  swatches.forEach((b, i) => { b.setAttribute('aria-checked', String(i === colour)); b.tabIndex = i === colour ? 0 : -1; });
  $('[data-cname]').textContent = col.name;
  $('[data-pcolour]').textContent = col.name;
  $('[data-price]').innerHTML = col.was
    ? '<span class="mco-quick-now">€' + col.price + '</span><s><span class="mco-quick-sr">was </span>€' + col.was + '</s><span class="mco-quick-off">−' + Math.round((1 - col.price / col.was) * 100) + '%</span>'
    : '<span class="mco-quick-now">€' + col.price + '</span>';
  paintSizes();
  if (!busy) idleMsg();
  if (animate && !reduce.matches) {
    art.animate([{ transform: 'none' }, { transform: 'translateY(-8px) rotate(-1.5deg)', offset: .32 }, { transform: 'none' }],
      { duration: 640, easing: 'cubic-bezier(.3,.7,.2,1)' });
  }
}

function setOpen(v, focusBack) {
  clearTimeout(closeT);
  if (v) {
    root.setAttribute('data-open', '');
    openBtn.setAttribute('aria-expanded', 'true');
    idleMsg();
    const first = sizes.find((b) => !isOut(b)) || sizes[0];
    sizes.forEach((b) => { b.tabIndex = b === first ? 0 : -1; });
    first.focus({ preventScroll: true });
  } else {
    const hadFocus = $('[data-panel]').contains(document.activeElement);
    root.removeAttribute('data-open');
    openBtn.setAttribute('aria-expanded', 'false');
    if (focusBack || hadFocus) openBtn.focus({ preventScroll: true });
  }
}

function fly(from, done) {
  if (reduce.matches) { done(); return; }
  const r0 = root.getBoundingClientRect(), a = from.getBoundingClientRect(), b = bagEl.querySelector('svg').getBoundingClientRect();
  const x0 = a.left + a.width / 2 - r0.left, y0 = a.top + a.height / 2 - r0.top;
  const x1 = b.left + b.width / 2 - r0.left, y1 = b.top + b.height / 2 - r0.top;
  const cx = (x0 + x1) / 2 - 24, cy = Math.max(6, Math.min(y0, y1) - 70);
  const dot = document.createElement('span');
  dot.className = 'mco-quick-dot';
  root.append(dot);
  const frames = [];
  for (let i = 0; i <= 20; i++) {
    const t = i / 20, u = 1 - t;
    const x = u * u * x0 + 2 * u * t * cx + t * t * x1, y = u * u * y0 + 2 * u * t * cy + t * t * y1;
    frames.push({ transform: 'translate(' + x.toFixed(1) + 'px,' + y.toFixed(1) + 'px) scale(' + (1.15 - t * .6).toFixed(3) + ')', opacity: t > .94 ? 0 : 1 });
  }
  dot.animate(frames, { duration: 680, easing: 'cubic-bezier(.45,.05,.3,1)' }).finished.then(() => { dot.remove(); done(); }, () => dot.remove());
}
function bump() {
  if (reduce.matches) return;
  bagEl.animate([{ transform: 'scale(1)' }, { transform: 'scale(1.18)', offset: .28 }, { transform: 'scale(.97)', offset: .62 }, { transform: 'scale(1)' }],
    { duration: 560, easing: 'cubic-bezier(.25,.8,.3,1)' });
}
function shake(b) {
  if (reduce.matches) return;
  b.animate([{ transform: 'none' }, { transform: 'translateX(-5px)' }, { transform: 'translateX(4px)' }, { transform: 'translateX(-2px)' }, { transform: 'none' }],
    { duration: 380, easing: 'cubic-bezier(.36,.07,.19,.97)' });
}

function add(b) {
  if (busy) return;
  const s = b.dataset.s, col = COLOURS[colour], key = colour + ':' + s;
  if (isOut(b)) {
    const nb = document.createElement('button');
    nb.type = 'button';
    nb.className = 'mco-quick-notify';
    nb.textContent = notified.has(key) ? 'You’re on the list' : 'Email me when it’s back';
    nb.disabled = notified.has(key);
    nb.addEventListener('click', () => {
      notified.add(key);
      setMsg('Done — we’ll email you when ' + s + ' in ' + col.name + ' is back.', 'ok');
      b.focus({ preventScroll: true });
    });
    setMsg(s + ' in ' + col.name + ' is sold out.', 'warn', nb);
    return;
  }
  if ((bag[key] || 0) >= LIMIT) {
    setMsg('Limit ' + LIMIT + ' per customer — you already have ' + bag[key] + ' × ' + s + ' in ' + col.name + '.', 'err');
    shake(b);
    return;
  }
  busy = true;
  root.setAttribute('data-busy', '');
  b.setAttribute('data-busy', '');
  b.setAttribute('aria-busy', 'true');
  setMsg('Adding ' + s + ' to your bag…');
  setTimeout(() => {
    if (!root.isConnected) return;
    busy = false;
    root.removeAttribute('data-busy');
    b.removeAttribute('data-busy');
    b.removeAttribute('aria-busy');
    bag[key] = (bag[key] || 0) + 1;
    col.stock[s] -= 1;
    paintSizes();
    setMsg('Added ' + s + ' · ' + col.name + ' to your bag', 'ok');
    fly(b, () => {
      count += 1;
      bagN.textContent = count;
      root.setAttribute('data-count', '');
      bagLive.textContent = count + (count === 1 ? ' item' : ' items') + ' in bag';
      bump();
    });
    closeT = setTimeout(() => {
      if (!root.isConnected || !root.hasAttribute('data-open')) return;
      setOpen(false);
      openLabel.textContent = 'Added';
      openBtn.setAttribute('data-done', '');
      clearTimeout(doneT);
      doneT = setTimeout(() => {
        if (!root.isConnected) return;
        openLabel.textContent = 'Quick add';
        openBtn.removeAttribute('data-done');
      }, 1800);
    }, 1100);
  }, 650);
}

root.addEventListener('click', (e) => {
  const t = e.target;
  if (t.closest('[data-opener]')) { setOpen(true); return; }
  if (t.closest('[data-close]')) { setOpen(false, true); return; }
  if (t.closest('.mco-quick-notify')) return;
  const sz = t.closest('.mco-quick-size');
  if (sz) { sizes.forEach((b) => { b.tabIndex = b === sz ? 0 : -1; }); add(sz); return; }
  const sw = t.closest('[data-sw] [role="radio"]');
  if (sw) { if (+sw.dataset.c !== colour) { colour = +sw.dataset.c; paintColour(true); } return; }
  if (root.hasAttribute('data-open') && !t.closest('[data-tray]')) setOpen(false);
});

root.addEventListener('keydown', (e) => {
  if (e.key === 'Escape' && root.hasAttribute('data-open')) { e.preventDefault(); setOpen(false, true); return; }
  const sz = e.target.closest('.mco-quick-size');
  if (sz) {
    const i = sizes.indexOf(sz);
    const n = { ArrowRight: i + 1, ArrowLeft: i - 1, Home: 0, End: sizes.length - 1 }[e.key];
    if (n === undefined) return;
    e.preventDefault();
    const nx = sizes[(n + sizes.length) % sizes.length];
    sizes.forEach((b) => { b.tabIndex = b === nx ? 0 : -1; });
    nx.focus();
    return;
  }
  const sw = e.target.closest('[data-sw] [role="radio"]');
  if (sw) {
    const d = { ArrowRight: 1, ArrowDown: 1, ArrowLeft: -1, ArrowUp: -1 }[e.key];
    if (!d) return;
    e.preventDefault();
    colour = (colour + d + COLOURS.length) % COLOURS.length;
    paintColour(true);
    swatches[colour].focus();
  }
});

paintColour(false);

