@property --mco-reviews-ft { syntax: "<length>"; inherits: false; initial-value: 0px; }
@property --mco-reviews-fb { syntax: "<length>"; inherits: false; initial-value: 0px; }
@keyframes mco-reviews-edges { 0% { --mco-reviews-ft: 0px; --mco-reviews-fb: 28px; } 8% { --mco-reviews-ft: 28px; } 92% { --mco-reviews-fb: 28px; } 100% { --mco-reviews-ft: 28px; --mco-reviews-fb: 0px; } }
@keyframes mco-reviews-shimmer { to { translate: 100% 0; } }
@keyframes mco-reviews-plus { 0% { opacity: 0; translate: 0 4px; } 30% { opacity: 1; } 100% { opacity: 0; translate: 0 -14px; } }

.mco-reviews {
  /* re-theme with these four */
  --mco-reviews-bg: oklch(0.205 0.008 70);
  --mco-reviews-ink: oklch(0.95 0.012 85);
  --mco-reviews-accent: oklch(0.84 0.135 80);
  --mco-reviews-low: oklch(0.7 0.12 38);

  --mco-reviews-muted: color-mix(in oklch, var(--mco-reviews-ink) 58%, var(--mco-reviews-bg));
  --mco-reviews-faint: color-mix(in oklch, var(--mco-reviews-ink) 34%, var(--mco-reviews-bg));
  --mco-reviews-line: color-mix(in oklch, var(--mco-reviews-ink) 10%, transparent);
  --mco-reviews-raise: color-mix(in oklch, var(--mco-reviews-ink) 4.5%, transparent);
  --mco-reviews-hl: color-mix(in oklch, var(--mco-reviews-accent) 16%, transparent);
  --mco-reviews-out: cubic-bezier(.2, .85, .25, 1);
  --mco-reviews-spring: linear(0, 0.009, 0.035 2.1%, 0.141 4.4%, 0.723 12.9%, 0.938 16.7%, 1.017 19.4%, 1.077 22.4%, 1.101 25.5%, 1.096 28.9%, 1.065 34.1%, 1.016 42.2%, 0.997 49.1%, 0.991 56.4%, 1.001 76.4%, 1);

  container-type: inline-size;
  position: relative; box-sizing: border-box; width: 100%; min-height: 158px;
  display: grid; gap: 12px; align-content: start;
  padding: 16px 16px 6px;
  border-radius: 18px; border: 1px solid var(--mco-reviews-line);
  background: radial-gradient(90% 60% at 0% 0%, color-mix(in oklch, var(--mco-reviews-accent) 8%, transparent), transparent 70%), var(--mco-reviews-bg);
  color: var(--mco-reviews-ink);
  font: 400 13px/1.45 system-ui, -apple-system, "Segoe UI", sans-serif;
  -webkit-font-smoothing: antialiased;

  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(button) { font: inherit; color: inherit; background: none; border: 0; padding: 0; margin: 0; cursor: pointer; }
  & :where(p, h3, ol) { margin: 0; }
  & :where(svg) { display: block; flex: none; fill: none; stroke: currentColor; stroke-width: 1.5; stroke-linecap: round; stroke-linejoin: round; }
  & :focus-visible { outline: 2px solid var(--mco-reviews-accent); outline-offset: 2px; }

  /* ---------- summary ---------- */
  & .mco-reviews-head { display: grid; gap: 0 14px; grid-template-columns: minmax(0, 1fr); grid-template-areas: "intro" "score" "hist"; }
  & .mco-reviews-intro { grid-area: intro; min-width: 0; }
  & .mco-reviews-hist { grid-area: hist; margin-top: 14px; }
  & .mco-reviews-score { grid-area: score; display: grid; grid-template-columns: auto 1fr; grid-template-areas: "avg stars" "avg meta"; column-gap: 12px; align-items: end; }
  & .mco-reviews-eyebrow { font-size: 10.5px; font-weight: 650; letter-spacing: .08em; text-transform: uppercase; color: var(--mco-reviews-muted); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & .mco-reviews-title { margin: 2px 0 8px; font-size: clamp(16px, 5cqi, 19px); font-weight: 680; letter-spacing: -.015em; text-wrap: balance; }
  & .mco-reviews-avg {
    grid-area: avg; display: grid; line-height: 1;
    & b { font-size: clamp(36px, 13cqi, 46px); font-weight: 760; letter-spacing: -.04em; font-variant-numeric: tabular-nums; }
    & span { margin-top: 4px; font-size: 10.5px; font-weight: 600; letter-spacing: .06em; text-transform: uppercase; color: var(--mco-reviews-muted); }
  }
  & .mco-reviews-stars {
    grid-area: stars; position: relative; display: block; width: 86px; height: 17px; align-self: end;
    & svg { position: absolute; inset: 0; width: 100%; height: 100%; stroke: none; fill: var(--mco-reviews-line); }
    & .mco-reviews-sfill { fill: var(--mco-reviews-accent); clip-path: inset(0 calc((1 - var(--v) / 5) * 100%) 0 0); }
  }
  & .mco-reviews-meta { grid-area: meta; font-size: 12px; color: var(--mco-reviews-muted); font-variant-numeric: tabular-nums; padding-bottom: 2px; }

  /* ---------- histogram (each bar filters) ---------- */
  & .mco-reviews-hist { display: grid; gap: 2px; align-content: center; }
  & .mco-reviews-bar {
    display: grid; grid-template-columns: 30px minmax(0, 1fr) 3ch; align-items: center; gap: 8px;
    height: 22px; padding: 0 6px; margin: 0 -6px; border-radius: 7px;
    font-variant-numeric: tabular-nums; font-size: 12px;
    transition: background-color .15s, opacity .25s;
    &:hover { background: var(--mco-reviews-raise); }
    &[aria-pressed="true"] { background: var(--mco-reviews-hl); }
  }
  & .mco-reviews-bl { display: inline-flex; align-items: center; gap: 3px; font-weight: 650;
    & svg { width: 11px; height: 11px; stroke: none; fill: var(--mco-reviews-faint); transition: fill .2s; }
  }
  & .mco-reviews-bar[aria-pressed="true"] .mco-reviews-bl svg { fill: var(--mco-reviews-accent); }
  & .mco-reviews-track { position: relative; height: 7px; border-radius: 4px; background: var(--mco-reviews-line); overflow: hidden; }
  & .mco-reviews-fill {
    position: absolute; inset: 0; border-radius: inherit; background: var(--mco-reviews-accent);
    transform-origin: left; scale: var(--p) 1;
    transition: scale 1s var(--mco-reviews-out) calc(var(--i) * 70ms), background-color .25s, opacity .25s;
    @starting-style { scale: 0 1; }
  }
  & .mco-reviews-bar:is([data-r="1"], [data-r="2"]) .mco-reviews-fill { background: var(--mco-reviews-low); }
  & .mco-reviews-n { text-align: right; color: var(--mco-reviews-muted); }
  & .mco-reviews-hist:has([aria-pressed="true"]) .mco-reviews-bar[aria-pressed="false"] { opacity: .5; }
  & .mco-reviews-hist:has([aria-pressed="true"]) .mco-reviews-bar[aria-pressed="false"]:hover { opacity: .85; }

  /* ---------- tools ---------- */
  & .mco-reviews-tools { display: flex; align-items: center; justify-content: space-between; gap: 8px; padding-top: 12px; border-top: 1px solid var(--mco-reviews-line); }
  & .mco-reviews-sort {
    display: inline-flex; padding: 2px; border-radius: 9px; background: var(--mco-reviews-raise); box-shadow: inset 0 0 0 1px var(--mco-reviews-line);
    & [role="radio"] { height: 26px; padding: 0 9px; border-radius: 7px; font-size: 12px; font-weight: 550; color: var(--mco-reviews-muted); white-space: nowrap; transition: background-color .2s, color .2s; }
    & [role="radio"]:hover { color: var(--mco-reviews-ink); }
    & [aria-checked="true"] { background: var(--mco-reviews-ink); color: var(--mco-reviews-bg); }
    & [aria-checked="true"]:hover { color: var(--mco-reviews-bg); }
  }
  & .mco-reviews-chip {
    display: inline-flex; align-items: center; gap: 5px; height: 30px; padding: 0 10px 0 8px; border-radius: 15px;
    font-size: 12px; font-weight: 550; color: var(--mco-reviews-muted); box-shadow: inset 0 0 0 1px var(--mco-reviews-line);
    transition: background-color .2s, color .2s, box-shadow .2s;
    & svg { width: 15px; height: 15px; }
    &:hover { color: var(--mco-reviews-ink); }
    &[aria-pressed="true"] { color: var(--mco-reviews-accent); background: var(--mco-reviews-hl); box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--mco-reviews-accent) 45%, transparent); }
  }
  & .mco-reviews-status { margin-top: -4px; font-size: 11.5px; color: var(--mco-reviews-muted); font-variant-numeric: tabular-nums; text-wrap: pretty;
    & b { color: var(--mco-reviews-ink); font-weight: 600; }
  }

  /* ---------- list: its own scroller, edges fade in as you scroll (scroll-driven mask) ---------- */
  & .mco-reviews-scroll {
    max-height: 262px; overflow: auto; overscroll-behavior: contain; margin: 0 -16px; padding: 2px 16px 12px;
    scrollbar-width: thin; scrollbar-color: var(--mco-reviews-line) transparent;
    mask-image: linear-gradient(to bottom, transparent, #000 var(--mco-reviews-ft), #000 calc(100% - var(--mco-reviews-fb)), transparent);
    &:focus-visible { outline-offset: -2px; border-radius: 8px; }
  }
  @supports (animation-timeline: scroll()) {
    & .mco-reviews-scroll { animation: mco-reviews-edges linear both; animation-timeline: scroll(self); }
  }
  & .mco-reviews-list { list-style: none; padding: 0; display: grid; gap: 8px; }
  & .mco-reviews-item {
    padding: 11px 12px 9px; border-radius: 12px; background: var(--mco-reviews-raise); box-shadow: inset 0 0 0 1px var(--mco-reviews-line);
    display: grid; gap: 5px;
    &:focus-visible { outline-offset: -2px; }
    &.is-new {
      transition: opacity .45s var(--mco-reviews-out), translate .55s var(--mco-reviews-spring), filter .45s;
      transition-delay: calc(var(--i, 0) * 55ms);
      @starting-style { opacity: 0; translate: 0 10px; filter: blur(3px); }
    }
  }
  & .mco-reviews-ihead { display: flex; align-items: center; gap: 8px; min-width: 0;
    & b { font-size: 13px; font-weight: 650; letter-spacing: -.005em; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  }
  & .mco-reviews-mini {
    position: relative; display: block; flex: none; width: 58px; height: 11.5px;
    & svg { position: absolute; inset: 0; width: 100%; height: 100%; stroke: none; fill: var(--mco-reviews-line); }
    & svg + svg { fill: var(--mco-reviews-accent); clip-path: inset(0 calc((1 - var(--v) / 5) * 100%) 0 0); }
    &[data-low] svg + svg { fill: var(--mco-reviews-low); }
  }
  & .mco-reviews-body { font-size: 12.5px; color: color-mix(in oklch, var(--mco-reviews-ink) 82%, var(--mco-reviews-bg)); text-wrap: pretty; }
  & .mco-reviews-foot { display: flex; align-items: center; gap: 6px; font-size: 11.5px; color: var(--mco-reviews-muted); font-variant-numeric: tabular-nums; min-width: 0; }
  & .mco-reviews-who { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; min-width: 4ch; flex: 0 1 auto; }
  & .mco-reviews-foot time { white-space: nowrap; }
  & .mco-reviews-ver { display: inline-flex; align-items: center; gap: 3px; color: var(--mco-reviews-accent); white-space: nowrap;
    & svg { width: 12px; height: 12px; stroke-width: 1.7; }
  }
  & .mco-reviews-help {
    position: relative; margin-left: auto; display: inline-flex; align-items: center; gap: 5px; height: 26px; padding: 0 8px; border-radius: 13px;
    color: var(--mco-reviews-muted); font-size: 11.5px; white-space: nowrap; font-variant-numeric: tabular-nums;
    transition: background-color .15s, color .15s;
    & svg { width: 13px; height: 13px; transition: scale .4s var(--mco-reviews-spring), rotate .4s var(--mco-reviews-spring); }
    &:hover { background: var(--mco-reviews-raise); color: var(--mco-reviews-ink); }
    &[aria-pressed="true"] { color: var(--mco-reviews-accent);
      & svg { fill: color-mix(in oklch, var(--mco-reviews-accent) 30%, transparent); scale: 1.15; rotate: -12deg; }
    }
    & .mco-reviews-plus { position: absolute; right: 6px; top: -6px; font-weight: 700; color: var(--mco-reviews-accent); pointer-events: none; animation: mco-reviews-plus .7s var(--mco-reviews-out) both; }
  }

  /* loading skeletons */
  & .mco-reviews-skel {
    position: relative; overflow: hidden; height: 92px; border-radius: 12px; background: var(--mco-reviews-raise);
    &::before { content: ""; position: absolute; inset: 14px 12px auto; height: 10px; width: 46%; border-radius: 5px; background: var(--mco-reviews-line);
      box-shadow: 0 22px 0 0 var(--mco-reviews-line), 0 38px 0 0 var(--mco-reviews-line); }
    &::after { content: ""; position: absolute; inset: 0; translate: -100% 0; background: linear-gradient(90deg, transparent, color-mix(in oklch, var(--mco-reviews-ink) 7%, transparent), transparent); animation: mco-reviews-shimmer 1.1s linear infinite; }
  }

  & .mco-reviews-more {
    width: 100%; height: 36px; margin-top: 8px; border-radius: 10px; font-size: 12.5px; font-weight: 600;
    box-shadow: inset 0 0 0 1px var(--mco-reviews-line); transition: background-color .15s, color .15s;
    &:hover:not(:disabled) { background: var(--mco-reviews-raise); }
    &:disabled { cursor: default; color: var(--mco-reviews-faint); box-shadow: none; }
    &[aria-busy="true"] { color: var(--mco-reviews-muted); cursor: progress; }
  }

  /* empty state */
  & .mco-reviews-empty {
    display: grid; justify-items: center; gap: 6px; padding: 22px 10px 14px; text-align: center; color: var(--mco-reviews-muted);
    transition: opacity .3s, translate .4s var(--mco-reviews-out);
    @starting-style { opacity: 0; translate: 0 6px; }
    &[hidden] { display: none; }
    & svg { width: 34px; height: 34px; color: var(--mco-reviews-faint); stroke-width: 1.4; }
    & p { font-size: 12.5px; text-wrap: balance; max-width: 30ch; }
    & button { margin-top: 4px; height: 30px; padding: 0 12px; border-radius: 15px; font-size: 12px; font-weight: 650; background: var(--mco-reviews-ink); color: var(--mco-reviews-bg); }
  }

  @container (min-width: 330px) {
    & .mco-reviews-head { grid-template-columns: auto minmax(0, 1fr); grid-template-areas: "intro intro" "score hist"; align-items: center; column-gap: 22px; }
    & .mco-reviews-hist { margin-top: 0; }
    & .mco-reviews-score { grid-template-columns: auto; grid-template-areas: "avg" "stars" "meta"; row-gap: 6px; align-items: start; }
    & .mco-reviews-meta { max-width: 15ch; text-wrap: balance; }
  }
  @container (max-width: 300px) {
    & .mco-reviews-help > span:first-of-type { display: none; }
    & .mco-reviews-help { padding: 0 6px; }
  }
  @container (max-width: 330px) {
    & .mco-reviews-tools { flex-wrap: wrap; }
    & .mco-reviews-sort [role="radio"] { padding: 0 7px; }
    & .mco-reviews-chip { padding: 0 9px 0 7px; }
  }
}

@media (prefers-reduced-motion: reduce) {
  .mco-reviews {
    & .mco-reviews-fill { transition: none; @starting-style { scale: var(--p) 1; } }
    & .mco-reviews-item.is-new { transition: opacity .2s; transition-delay: 0s; @starting-style { opacity: 0; translate: none; filter: none; } }
    & .mco-reviews-skel::after { animation: none; }
    & .mco-reviews-help svg { transition: none; }
    & .mco-reviews-help[aria-pressed="true"] svg { scale: none; rotate: none; }
    & .mco-reviews-help .mco-reviews-plus { display: none; }
    & .mco-reviews-empty { transition: opacity .2s; @starting-style { opacity: 0; translate: none; } }
  }
}

