const $ = (s) => root.querySelector(s);
const RM = matchMedia('(prefers-reduced-motion: reduce)');
const PAGE = 4;
const STAR = 'M8 1.6l1.9 3.9 4.3.6-3.1 3 .7 4.3L8 11.4l-3.8 2 .7-4.3-3.1-3 4.3-.6z';
const ROW = [0, 1, 2, 3, 4].map((i) => '<path transform="translate(' + i * 16 + ' 0)" d="' + STAR + '"/>').join('');
const R = [
  { id: 1, r: 5, t: 'Survived a week of ferries', b: 'Packed it for six islands in eight days. The waxed canvas shrugged off sea spray and the base stayed dry on wet decks.', n: 'Ines M.', v: 1, d: '2026-09-28', h: 14 },
  { id: 2, r: 5, t: 'Fits under the seat, just', b: 'Squeezed under a budget-airline seat with the side pockets empty. Full, it’s a cabin bag — plan accordingly.', n: 'Tomasz K.', v: 1, d: '2026-09-21', h: 31 },
  { id: 3, r: 4, t: 'Strap needs more padding', b: 'Brass hardware feels heirloom-grade. The shoulder pad slides around once it’s loaded past 10 kg.', n: 'Priya S.', v: 1, d: '2026-09-14', h: 22 },
  { id: 4, r: 5, t: 'The patina is the point', b: 'Six months in and the creases have gone dark and soft. It looks better every trip, which is more than I can say for me.', n: 'Callum R.', v: 1, d: '2026-08-30', h: 18 },
  { id: 5, r: 1, t: 'Zip split on day two', b: 'The main zip separated behind the slider on the second day. Support sent a replacement within a week, but I wanted it to just work.', n: 'Dana W.', v: 1, d: '2026-08-22', h: 9 },
  { id: 6, r: 5, t: 'Gym bag that passes as luggage', b: 'The shoe pocket at the end keeps trainers away from work clothes, and it wipes clean with a damp cloth.', n: 'Marco B.', v: 1, d: '2026-08-11', h: 6 },
  { id: 7, r: 4, t: 'Smells of wax for a while', b: 'The wax smell lasted about three weeks; a day airing in the sun helped. Otherwise exactly as described.', n: 'Hannah L.', v: 1, d: '2026-07-29', h: 11 },
  { id: 8, r: 3, t: 'Heavier than I expected', b: 'Empty it weighs 1.9 kg, which eats into a carry-on allowance. Beautifully made, just not for ultralight travel.', n: 'Oskar N.', v: 1, d: '2026-07-12', h: 27 },
  { id: 9, r: 5, t: 'Bought a second for my partner', b: 'The olive and the tobacco look great side by side, and we finally stop grabbing each other’s bag.', n: 'Leah G.', v: 1, d: '2026-06-30', h: 4 },
  { id: 10, r: 2, t: 'Colour not as pictured', b: 'Mine arrived noticeably greener than the photos. Quality is fine, but I’d hoped for the warmer brown.', n: 'Guest reviewer', v: 0, d: '2026-06-18', h: 7 },
  { id: 11, r: 5, t: 'The laptop sleeve is a bonus', b: 'The padded sleeve takes a 14-inch laptop and its charger. Barely advertised, but it’s why I use it for work trips.', n: 'Kwame A.', v: 1, d: '2026-06-02', h: 16 },
  { id: 12, r: 4, t: 'Great bag, slow delivery', b: 'Took nine days to arrive. The bag itself is excellent — reinforced corners and a proper leather base.', n: 'Sofia P.', v: 1, d: '2026-05-19', h: 3 },
  { id: 13, r: 5, t: 'Rewaxed it after a year', b: 'The included wax bar covered a full rewax after twelve months. Twenty minutes with a hairdryer and it’s like new.', n: 'Ruth E.', v: 1, d: '2026-04-27', h: 25 },
  { id: 14, r: 5, t: 'Handles stay upright', b: 'The stiffened handles don’t flop when you set it down, so it’s easy to grab off a luggage rack.', n: 'Jun H.', v: 1, d: '2026-04-08', h: 5 },
  { id: 15, r: 4, t: 'Wish it had a trolley sleeve', b: 'Would be perfect with a pass-through for suitcase handles. Still my go-to for weekends away.', n: 'Elif D.', v: 1, d: '2026-03-15', h: 12 },
  { id: 16, r: 5, t: 'Better than my old leather one', b: 'Lighter than the leather holdall it replaced and it doesn’t mind rain. Inner pockets keep cables tidy.', n: 'Noah F.', v: 1, d: '2026-02-21', h: 8 }
