const esc = (s) => String(s).replace(/[&<>"]/g, (c) => '&#' + c.charCodeAt(0) + ';');
const list = $('[data-list]'), scroller = $('[data-scroll]'), more = $('[data-more]'), status = $('[data-status]');
const empty = $('[data-empty]'), bars = Array.from(root.querySelectorAll('.mco-reviews-bar'));
const sortBtns = Array.from(root.querySelectorAll('[data-sort] [role="radio"]')), verBtn = $('[data-verified]');
const st = { stars: new Set(), verified: false, sort: 'helpful', shown: PAGE, voted: new Set(), loading: false };

/* summary: every figure comes from the review array, so the histogram, average and list always agree */
(function summary() {
  const total = R.length, sum = R.reduce((a, x) => a + x.r, 0), avg = sum / total;
  const rec = Math.round(R.filter((x) => x.r >= 4).length / total * 100);
  $('[data-avg]').textContent = avg.toFixed(1);
  const s = $('[data-avgstars]');
