      '<svg viewBox="0 0 80 16" aria-hidden="true">' + ROW + '</svg><svg viewBox="0 0 80 16" aria-hidden="true">' + ROW + '</svg></span><b>' + esc(x.t) + '</b></div>' +
    '<p class="mco-reviews-body">' + esc(x.b) + '</p>' +
    '<div class="mco-reviews-foot"><span class="mco-reviews-who">' + esc(x.n) + '</span>' +
      (x.v ? '<span class="mco-reviews-ver"><svg viewBox="0 0 16 16" aria-hidden="true"><path d="M3.5 8.3l2.8 2.8 6.2-6.6"/></svg>Verified</span>' : '') +
      '<span aria-hidden="true">·</span><time datetime="' + x.d + '">' + fDate.format(new Date(x.d + 'T12:00')) + '</time>' +
      '<button type="button" class="mco-reviews-help" aria-pressed="false" data-help="' + x.id + '"><svg viewBox="0 0 16 16" aria-hidden="true"><path d="M5 7.2v6.3H2.6V7.2zM5 7.2l2.6-4.9c1.1 0 1.9.9 1.7 2L8.9 6.6h3.6c.9 0 1.5.8 1.3 1.7l-1 4.1c-.2.7-.8 1.1-1.5 1.1H5"/></svg>' +
