function render(opts) {
  opts = opts || {};
  const all = sorted(matches());
  const vis = all.slice(0, st.shown);
  const first = new Map();
  if (!RM.matches) list.querySelectorAll('.mco-reviews-item').forEach((li) => first.set(li.dataset.id, li.getBoundingClientRect().top));
  const have = new Map(Array.from(list.querySelectorAll('.mco-reviews-item')).map((li) => [li.dataset.id, li]));
  let k = 0, firstNew = null;
  const nodes = vis.map((x) => {
    let li = have.get(String(x.id));
    if (!li) {
      li = card(x);
      li.classList.add('is-new');
