  status.innerHTML = total ? 'Showing <b>' + vis.length + '</b> of <b>' + total + '</b> ' + (total === 1 ? 'review' : 'reviews') + (filt.length ? ' · ' + esc(filt.join(' · ')) : '') : 'No matches' + (filt.length ? ' · ' + esc(filt.join(' · ')) : '');
  if (opts.focusNew && firstNew) firstNew.focus({ preventScroll: false });
