function changeFilter() {
  st.shown = PAGE;
  scroller.scrollTop = 0;
  render();
}
function setBarFocus(b) { bars.forEach((x) => { x.tabIndex = x === b ? 0 : -1; }); b.focus(); }

root.addEventListener('click', (e) => {
  const bar = e.target.closest('.mco-reviews-bar');
  if (bar) {
