    verBtn.setAttribute('aria-pressed', 'false');
    changeFilter();
    bars[0].focus();
    return;
  }
  const h = e.target.closest('[data-help]');
  if (h) {
    const id = +h.dataset.help, x = R.find((y) => y.id === id), on = !st.voted.has(id);
    if (on) st.voted.add(id); else st.voted.delete(id);
