root.addEventListener('keydown', (e) => {
  const bar = e.target.closest('.mco-reviews-bar');
  if (bar) {
    const i = bars.indexOf(bar);
    const n = { ArrowDown: i + 1, ArrowUp: i - 1, Home: 0, End: bars.length - 1 }[e.key];
    if (n !== undefined) { e.preventDefault(); setBarFocus(bars[(n + bars.length) % bars.length]); return; }
  }
  const so = e.target.closest('[data-sort] [role="radio"]');
  if (so) {
    const i = sortBtns.indexOf(so);
    const n = { ArrowRight: i + 1, ArrowDown: i + 1, ArrowLeft: i - 1, ArrowUp: i - 1 }[e.key];
