@property --mco-receipt-c { syntax: "<integer>"; inherits: true; initial-value: 0; }
@property --mco-receipt-e { syntax: "<integer>"; inherits: true; initial-value: 0; }
@property --mco-receipt-m { syntax: "<integer>"; inherits: true; initial-value: 0; }
@keyframes mco-receipt-stamp { 0% { opacity: 0; scale: 1.9; rotate: -2deg; } 55% { opacity: 1; scale: .94; rotate: -9deg; } 100% { opacity: .92; scale: 1; rotate: -8deg; } }
@keyframes mco-receipt-shake { 20%, 60% { translate: -5px 0; } 40%, 80% { translate: 4px 0; } }
@keyframes mco-receipt-spin { to { rotate: 360deg; } }

.mco-receipt {
  /* re-theme with these four */
  --mco-receipt-paper: oklch(0.985 0.006 95);
  --mco-receipt-ink: oklch(0.24 0.012 255);
  --mco-receipt-stampc: oklch(0.55 0.19 27);
  --mco-receipt-ok: oklch(0.5 0.12 155);

  --mco-receipt-muted: color-mix(in oklch, var(--mco-receipt-ink) 56%, var(--mco-receipt-paper));
  --mco-receipt-faint: color-mix(in oklch, var(--mco-receipt-ink) 30%, var(--mco-receipt-paper));
  --mco-receipt-rule: color-mix(in oklch, var(--mco-receipt-ink) 22%, transparent);
  --mco-receipt-wash: color-mix(in oklch, var(--mco-receipt-ink) 5%, transparent);
  --mco-receipt-mono: ui-monospace, Menlo, "SF Mono", Consolas, monospace;
  --mco-receipt-out: cubic-bezier(.2, .85, .25, 1);
  --mco-receipt-z: 9px;

  container-type: inline-size;
  position: relative; box-sizing: border-box; width: 100%; max-width: 400px; margin-inline: auto; min-height: 158px;
  filter: drop-shadow(0 14px 18px oklch(0.15 0.02 260 / .28)) drop-shadow(0 1px 1px oklch(0.15 0.02 260 / .2));
  color: var(--mco-receipt-ink);
  font: 400 13px/1.4 system-ui, -apple-system, "Segoe UI", sans-serif;
  -webkit-font-smoothing: antialiased;

  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(button, input, output) { font: inherit; color: inherit; background: none; border: 0; padding: 0; margin: 0; }
  & :where(button) { cursor: pointer; }
  & :where(p, ul, dl, dd) { margin: 0; }
  & :where(svg) { display: block; flex: none; fill: none; stroke: currentColor; stroke-width: 1.5; stroke-linecap: round; stroke-linejoin: round; }
  & :focus-visible { outline: 2px solid var(--mco-receipt-ink); outline-offset: 2px; }
  & .mco-receipt-sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }

  /* the paper: torn zig-zag top and bottom from two conic-gradient masks */
  & .mco-receipt-paper {
    display: grid; gap: 12px;
    padding: calc(var(--mco-receipt-z) + 14px) clamp(14px, 5.5cqi, 22px) calc(var(--mco-receipt-z) + 12px);
    background:
      repeating-linear-gradient(0deg, transparent 0 3px, oklch(0.5 0.02 90 / .018) 3px 4px),
      var(--mco-receipt-paper);
    --_m: conic-gradient(from -45deg at bottom, #0000, #000 1deg 89deg, #0000 90deg) 50% 100% / calc(2 * var(--mco-receipt-z)) 51% repeat-x,
          conic-gradient(from 135deg at top, #0000, #000 1deg 89deg, #0000 90deg) 50% 0 / calc(2 * var(--mco-receipt-z)) 51% repeat-x;
    -webkit-mask: var(--_m); mask: var(--_m);
  }

  /* ---------- header ---------- */
  & .mco-receipt-head { display: grid; justify-items: center; gap: 2px; text-align: center; padding-bottom: 12px; border-bottom: 1.5px dashed var(--mco-receipt-rule); }
  & .mco-receipt-shop { font-size: clamp(17px, 6cqi, 21px); font-weight: 800; letter-spacing: .22em; text-transform: uppercase; text-wrap: balance; padding-left: .22em; }
  & .mco-receipt-sub { font-size: 12px; color: var(--mco-receipt-muted); }
  & .mco-receipt-meta { display: flex; gap: 10px; font: 500 10.5px/1.4 var(--mco-receipt-mono); letter-spacing: .04em; color: var(--mco-receipt-muted); font-variant-numeric: tabular-nums; }

  /* ---------- lines ---------- */
  & .mco-receipt-lines { list-style: none; padding: 0; display: grid; gap: 9px; padding-bottom: 12px; border-bottom: 1.5px dashed var(--mco-receipt-rule); }
  & .mco-receipt-line { display: grid; grid-template-columns: minmax(0, 1fr) auto 7ch; align-items: center; gap: 10px; }
  & .mco-receipt-name {
    display: grid; font-weight: 600; font-size: 13px; line-height: 1.25; min-width: 0;
    & small { font: 400 11px/1.4 var(--mco-receipt-mono); color: var(--mco-receipt-muted); font-variant-numeric: tabular-nums; }
  }
  & .mco-receipt-step {
    display: inline-grid; grid-template-columns: 24px 2.2ch 24px; align-items: center; height: 26px; border-radius: 13px;
    box-shadow: inset 0 0 0 1px var(--mco-receipt-rule);
    & button { width: 24px; height: 26px; display: grid; place-items: center; border-radius: 13px; color: var(--mco-receipt-muted); transition: color .15s, background-color .15s; }
    & button:hover:not(:disabled) { color: var(--mco-receipt-ink); background: var(--mco-receipt-wash); }
    & button:disabled { color: var(--mco-receipt-faint); cursor: not-allowed; opacity: .55; }
    & svg { width: 11px; height: 11px; stroke-width: 1.8; }
    & output { text-align: center; font: 600 12.5px/1 var(--mco-receipt-mono); font-variant-numeric: tabular-nums; }
  }
  & .mco-receipt-amt { text-align: right; font: 500 13px/1 var(--mco-receipt-mono); font-variant-numeric: tabular-nums; }

  /* ---------- sums: dotted leaders, rows print in line by line ---------- */
  & .mco-receipt-sums { display: grid; gap: 5px; font-size: 12.5px; }
  & .mco-receipt-row {
    display: flex; align-items: baseline; gap: 6px;
    & dt { display: inline-flex; align-items: baseline; gap: 6px; min-width: 0; white-space: nowrap; }
    & dt span { font-size: 11px; color: var(--mco-receipt-muted); overflow: hidden; text-overflow: ellipsis; }
    &::after { content: ""; order: 1; flex: 1; min-width: 12px; height: 1px; translate: 0 -3px; background: radial-gradient(circle, var(--mco-receipt-faint) .7px, transparent 1px) 0 0 / 5px 1px repeat-x; }
    & dd { order: 2; font: 500 12.5px/1 var(--mco-receipt-mono); font-variant-numeric: tabular-nums; }
    &.is-code dt b { font: 700 11.5px/1.5 var(--mco-receipt-mono); letter-spacing: .06em; padding: 0 5px; border-radius: 4px; background: var(--mco-receipt-wash); box-shadow: inset 0 0 0 1px var(--mco-receipt-rule); }
    &.is-code dd { color: var(--mco-receipt-stampc); font-weight: 650; }
    &.is-print { clip-path: inset(0 0 0 0); transition: clip-path .5s steps(7, end); @starting-style { clip-path: inset(0 0 100% 0); } }
  }
  & .mco-receipt-x {
    align-self: center; width: 18px; height: 18px; border-radius: 50%; display: grid; place-items: center; color: var(--mco-receipt-muted);
    & svg { width: 9px; height: 9px; stroke-width: 2; }
    &:hover { color: var(--mco-receipt-paper); background: var(--mco-receipt-ink); }
  }

  /* ---------- total: an @property integer of cents, printed by CSS counters ---------- */
  & .mco-receipt-total {
    position: relative; display: flex; align-items: baseline; gap: 8px; padding-top: 10px; border-top: 3px double var(--mco-receipt-rule);
  }
  & .mco-receipt-tl { font-size: 12px; font-weight: 800; letter-spacing: .2em; text-transform: uppercase; }
  & .mco-receipt-cur { font: 600 10.5px/1 var(--mco-receipt-mono); color: var(--mco-receipt-muted); }
  & .mco-receipt-tn {
    margin-left: auto; font: 700 clamp(22px, 8cqi, 28px)/1 var(--mco-receipt-mono); letter-spacing: -.03em; font-variant-numeric: tabular-nums;
    --mco-receipt-e: calc(var(--mco-receipt-c) / 100 - .5);
    --mco-receipt-m: calc(var(--mco-receipt-c) - var(--mco-receipt-e) * 100);
    counter-reset: mco-receipt-eur var(--mco-receipt-e) mco-receipt-cent var(--mco-receipt-m);
    transition: --mco-receipt-c .9s cubic-bezier(.16, 1, .3, 1);
    &::after { content: counter(mco-receipt-eur) "." counter(mco-receipt-cent, decimal-leading-zero); }
  }
  & .mco-receipt-stamp {
    position: absolute; left: 34%; top: -18px; pointer-events: none;
    padding: 4px 9px 3px; border: 2px solid currentColor; border-radius: 6px; outline: 1px solid currentColor; outline-offset: 2px;
    color: var(--mco-receipt-stampc); font: 800 11px/1.15 var(--mco-receipt-mono); letter-spacing: .12em; text-transform: uppercase; text-align: center; white-space: nowrap;
    rotate: -8deg; opacity: .92; mix-blend-mode: multiply;
    -webkit-mask: radial-gradient(circle at 30% 40%, #000 0 55%, #0008 80%) , repeating-radial-gradient(circle at 70% 30%, #000 0 1.2px, #000c 1.6px 2.4px);
    mask: radial-gradient(circle at 30% 40%, #000 0 55%, #0008 80%), repeating-radial-gradient(circle at 70% 30%, #000 0 1.2px, #000c 1.6px 2.4px);
    &[hidden] { display: none; }
    &.is-hit { animation: mco-receipt-stamp .5s cubic-bezier(.3, 1.4, .5, 1) both; }
    & small { display: block; font-size: 9px; letter-spacing: .18em; }
  }
  & .mco-receipt-vat { margin-top: -6px; text-align: right; font: 400 11px/1.3 var(--mco-receipt-mono); color: var(--mco-receipt-muted); font-variant-numeric: tabular-nums; }

  /* ---------- promo ---------- */
  & .mco-receipt-promo { display: grid; gap: 6px; padding-top: 12px; border-top: 1.5px dashed var(--mco-receipt-rule); }
  & .mco-receipt-field {
    display: grid; grid-template-columns: minmax(0, 1fr) auto; height: 38px; border-radius: 10px;
    background: var(--mco-receipt-paper); box-shadow: inset 0 0 0 1.5px var(--mco-receipt-rule);
    transition: box-shadow .2s;
    &:focus-within { box-shadow: inset 0 0 0 1.5px var(--mco-receipt-ink); }
    &.is-shake { animation: mco-receipt-shake .36s; }
  }
  & .mco-receipt-promo:has([aria-invalid="true"]) .mco-receipt-field { box-shadow: inset 0 0 0 1.5px var(--mco-receipt-stampc); }
  & .mco-receipt-in {
    display: flex; align-items: center; gap: 8px; padding-left: 11px; min-width: 0; cursor: text;
    & svg { width: 15px; height: 15px; color: var(--mco-receipt-muted); }
    & input { width: 100%; height: 100%; outline: none; font: 600 13px/1 var(--mco-receipt-mono); letter-spacing: .08em; text-transform: uppercase; }
    & input::placeholder { font-family: system-ui, -apple-system, "Segoe UI", sans-serif; letter-spacing: 0; text-transform: none; font-weight: 400; color: var(--mco-receipt-faint); }
    & input:read-only { color: var(--mco-receipt-muted); }
  }
  & .mco-receipt-apply {
    position: relative; margin: 4px; padding: 0 14px; border-radius: 7px; background: var(--mco-receipt-ink); color: var(--mco-receipt-paper);
    font-size: 12.5px; font-weight: 700; letter-spacing: .02em; transition: opacity .2s, background-color .2s, scale .2s;
    &:hover:not(:disabled) { background: color-mix(in oklch, var(--mco-receipt-ink) 84%, var(--mco-receipt-stampc)); }
    &:active:not(:disabled) { scale: .96; }
    &:disabled { opacity: .3; cursor: not-allowed; }
    &[aria-busy="true"] { opacity: 1; cursor: progress;
      & span { opacity: 0; }
      &::after { content: ""; position: absolute; inset: 0; margin: auto; width: 14px; height: 14px; border-radius: 50%; border: 2px solid color-mix(in oklch, var(--mco-receipt-paper) 30%, transparent); border-top-color: var(--mco-receipt-paper); animation: mco-receipt-spin .7s linear infinite; }
    }
  }
  & .mco-receipt-msg {
    min-height: 18px; display: flex; flex-wrap: wrap; align-items: center; gap: 4px 6px; font-size: 11.5px; color: var(--mco-receipt-muted); text-wrap: pretty;
    & svg { width: 13px; height: 13px; stroke-width: 1.8; align-self: start; margin-top: 1px; }
    & > span { flex: 1 1 0; min-width: 0; }
    &:has(> svg) { flex-wrap: nowrap; }
