    & [data-try]:hover { background: var(--mco-receipt-wash); }
    & b { color: var(--mco-receipt-ink); font-family: var(--mco-receipt-mono); letter-spacing: .04em; }
    &[data-tone="err"] { color: var(--mco-receipt-stampc); font-weight: 550; }
