  }

  & .mco-receipt-pay {
    display: flex; align-items: center; justify-content: space-between; height: 44px; padding: 0 16px; border-radius: 11px;
    background: var(--mco-receipt-ink); color: var(--mco-receipt-paper); font-size: 13.5px; font-weight: 650;
    transition: translate .3s var(--mco-receipt-out), box-shadow .3s;
