  }
}

js:
const $ = (s, el) => (el || root).querySelector(s);
const RM = matchMedia('(prefers-reduced-motion: reduce)');
const ITEMS = { mug: { unit: 1800, q: 2, max: 6 }, drip: { unit: 2900, q: 1, max: 3 }, bean: { unit: 1450, q: 1, max: 6 } };
const SHIP = 590, FREE_MIN = 7500, VAT = 21;
const CODES = {
  WELCOME10: { kind: 'pct', pct: 10, label: '10% off items' },
  FREESHIP: { kind: 'ship', label: 'free shipping' },
  AUTUMN25: { kind: 'expired', ended: '30 Sep 2026' }
};
const uid = 'mco-receipt-' + Math.random().toString(36).slice(2, 7);
const input = $('[data-code]'), apply = $('[data-apply]'), msg = $('[data-msg]'), form = $('[data-form]');
const sums = $('[data-sums]'), shipRow = $('[data-shiprow]'), stamp = $('[data-stamp]'), field = $('.mco-receipt-field');
const applied = [];
const IDLE = msg.innerHTML;
msg.id = uid + '-msg';
input.setAttribute('aria-describedby', msg.id);

const money = (c) => (c < 0 ? '−' : '') + (Math.abs(c) / 100).toFixed(2);
const eur = (c) => '€' + (c / 100).toFixed(2);
const X = '<svg viewBox="0 0 10 10" aria-hidden="true"><path d="M2 2l6 6M8 2 2 8"/></svg>';
const ICON = {
  err: '<svg viewBox="0 0 16 16" aria-hidden="true"><circle cx="8" cy="8" r="6.2"/><path d="M8 4.8v3.6M8 11v.1"/></svg>',
  ok: '<svg viewBox="0 0 16 16" aria-hidden="true"><path d="M3.2 8.4l3 3 6.6-7"/></svg>',
  warn: '<svg viewBox="0 0 16 16" aria-hidden="true"><path d="M8 2.2 14.4 13.5H1.6z"/><path d="M8 6.5v3M8 11.4v.1"/></svg>'
};

/* one function owns the maths, everything on the paper reads from it */
function totals() {
  const sub = Object.values(ITEMS).reduce((a, x) => a + x.unit * x.q, 0);
  const pct = applied.includes('WELCOME10') ? Math.round(sub * CODES.WELCOME10.pct / 100) : 0;
  const shipOff = applied.includes('FREESHIP') ? SHIP : 0;
  const total = sub - pct + SHIP - shipOff;
  return { sub, pct, shipOff, total, vat: Math.round(total * VAT / (100 + VAT)), saved: pct + shipOff, n: Object.values(ITEMS).reduce((a, x) => a + x.q, 0) };
}

function say(text, tone, html) {
  msg.dataset.tone = tone || '';
  msg.innerHTML = (tone && ICON[tone] ? ICON[tone] : '') + (html ? text : '<span></span>');
  if (!html) msg.lastElementChild.textContent = text;
}

let lastSaved = 0;
function paint() {
  const t = totals();
  root.querySelectorAll('.mco-receipt-line').forEach((li) => {
    const it = ITEMS[li.dataset.k];
    $('[data-q]', li).textContent = it.q;
    $('[data-amt]', li).textContent = money(it.unit * it.q);
    $('[data-d="-1"]', li).disabled = it.q <= 1;
    $('[data-d="1"]', li).disabled = it.q >= it.max;
  });
  $('[data-count]').textContent = t.n + (t.n === 1 ? ' item' : ' items');
  $('[data-sub]').textContent = money(t.sub);
  const pr = sums.querySelector('[data-code-row="WELCOME10"] dd');
  if (pr) pr.textContent = money(-t.pct);
  $('[data-ship]').textContent = money(SHIP);
  $('[data-total]').style.setProperty('--mco-receipt-c', t.total);
  $('[data-totalsr]').textContent = 'Total ' + eur(t.total);
  $('[data-paytotal]').textContent = eur(t.total);
  $('[data-vat]').textContent = 'Includes VAT (' + VAT + '%) ' + eur(t.vat);
  if (t.saved !== lastSaved) {
    stamp.hidden = !t.saved;
    if (t.saved) {
      stamp.innerHTML = '<small>You saved</small>' + eur(t.saved);
      stamp.classList.remove('is-hit'); void stamp.offsetWidth; stamp.classList.add('is-hit');
    }
    lastSaved = t.saved;
  }
}

/* rows below a change slide instead of jumping: measure, mutate, invert, play */
function flip(mutate) {
  const els = Array.from(root.querySelectorAll('.mco-receipt-row, .mco-receipt-total, .mco-receipt-vat, .mco-receipt-promo, .mco-receipt-pay, .mco-receipt-bars'));
  const before = new Map(els.map((el) => [el, el.getBoundingClientRect().top]));
  mutate();
  if (RM.matches) return;
  els.forEach((el) => {
    if (!el.isConnected) return;
    const dy = before.get(el) - el.getBoundingClientRect().top;
    if (Math.abs(dy) > .5) el.animate([{ transform: 'translateY(' + dy + 'px)' }, { transform: 'none' }], { duration: 420, easing: 'cubic-bezier(.2,.85,.25,1)' });
  });
}

function addRow(code) {
  const c = CODES[code];
  const row = document.createElement('div');
  row.className = 'mco-receipt-row is-code is-print';
  row.dataset.codeRow = code;
  row.innerHTML = '<dt><b>' + code + '</b><span>' + c.label + '</span><button type="button" class="mco-receipt-x" data-remove="' + code + '" aria-label="Remove code ' + code + '">' + X + '</button></dt><dd></dd>';
  flip(() => { if (c.kind === 'ship') sums.append(row); else sums.insertBefore(row, shipRow); });
  if (c.kind === 'ship') row.querySelector('dd').textContent = money(-SHIP);
}
function removeRow(code, quiet) {
  const row = sums.querySelector('[data-code-row="' + code + '"]');
  applied.splice(applied.indexOf(code), 1);
  const done = () => { flip(() => row.remove()); paint(); };
  if (RM.matches || !row) { if (row) row.remove(); paint(); }
  else row.animate([{ clipPath: 'inset(0 0 0 0)', opacity: 1 }, { clipPath: 'inset(0 0 100% 0)', opacity: 0 }], { duration: 220, easing: 'steps(5, end)' }).finished.then(done, done);
  if (!quiet) say(code + ' removed.', '');
}

function reject(text) {
  input.setAttribute('aria-invalid', 'true');
  say(text, 'err');
  if (!RM.matches) { field.classList.remove('is-shake'); void field.offsetWidth; field.classList.add('is-shake'); }
}

let busy = false;
form.addEventListener('submit', (e) => {
  e.preventDefault();
  const code = input.value.replace(/\s+/g, '').toUpperCase();
  if (!code || busy) return;
  busy = true;
  input.readOnly = true;
  apply.setAttribute('aria-busy', 'true');
  input.removeAttribute('aria-invalid');
  say('Checking ' + code + '…', '');
  setTimeout(() => {
    if (!root.isConnected) return;
    busy = false;
    input.readOnly = false;
    apply.removeAttribute('aria-busy');
    const c = CODES[code], t = totals();
    if (!c) return reject('We don’t recognise ' + code + '. Codes are case-insensitive — check for typos.');
    if (c.kind === 'expired') return reject(code + ' ended on ' + c.ended + '.');
    if (applied.includes(code)) return reject(code + ' is already on this order.');
    if (c.kind === 'ship' && t.sub < FREE_MIN) return reject('FREESHIP needs a ' + eur(FREE_MIN) + ' subtotal — add ' + eur(FREE_MIN - t.sub) + ' more.');
    applied.push(code);
    addRow(code);
    input.value = '';
    apply.disabled = true;
    paint();
    const saved = c.kind === 'pct' ? totals().pct : SHIP;
    say(code + ' applied — ' + eur(saved) + ' off.', 'ok');
    input.focus();
  }, 700);
});
input.addEventListener('input', () => {
  apply.disabled = !input.value.trim();
  if (input.getAttribute('aria-invalid')) { input.removeAttribute('aria-invalid'); say(IDLE, '', true); }
});
input.addEventListener('keydown', (e) => {
  if (e.key === 'Escape' && input.value) { e.preventDefault(); input.value = ''; apply.disabled = true; input.removeAttribute('aria-invalid'); say(IDLE, '', true); }
});

root.addEventListener('click', (e) => {
  const tr = e.target.closest('[data-try]');
  if (tr) { input.value = tr.textContent; apply.disabled = false; input.removeAttribute('aria-invalid'); form.requestSubmit(); return; }
  const rm = e.target.closest('[data-remove]');
  if (rm) { removeRow(rm.dataset.remove); input.focus(); return; }
  const st = e.target.closest('[data-d]');
  if (st && !st.disabled) {
    const it = ITEMS[st.closest('.mco-receipt-line').dataset.k];
    it.q = Math.max(1, Math.min(it.max, it.q + +st.dataset.d));
    if (applied.includes('FREESHIP') && totals().sub < FREE_MIN) {
      removeRow('FREESHIP', true);
      say('FREESHIP came off — the subtotal is now under ' + eur(FREE_MIN) + '.', 'warn');
    }
    paint();
    return;
  }
  if (e.target.closest('[data-pay]')) {
    const b = e.target.closest('[data-pay]');
    say('Payment opens in the next step — your total of ' + eur(totals().total) + ' is held for 15 minutes.', '');
    if (!RM.matches) b.animate([{ scale: 1 }, { scale: .97 }, { scale: 1 }], { duration: 260, easing: 'cubic-bezier(.3,.7,.3,1)' });
  }
});

/* header date and a barcode drawn from the order number */
const now = new Date();
$('[data-when]').textContent = now.toLocaleDateString('en-GB', { day: '2-digit', month: 'short', year: 'numeric' }) + ' · ' + now.toLocaleTimeString('en-GB', { hour: '2-digit', minute: '2-digit' });
(function bars() {
  let s = 20417, x = 0, h = '';
  while (x < 196) {
    s = (s * 9301 + 49297) % 233280;
    const w = 1 + (s % 3), gap = 1 + ((s >> 3) % 3);
    h += '<rect x="' + x + '" y="0" width="' + w + '" height="22" fill="currentColor" stroke="none"/>';
    x += w + gap;
  }
  $('[data-bars]').innerHTML = h;
})();
paint();

