@keyframes mco-fit-in { from { opacity: 0; translate: 0 .45em; filter: blur(2px); } }
@keyframes mco-fit-ok { from { scale: .4; opacity: 0; } }

.mco-fit {
  /* re-theme with these four */
  --mco-fit-bg: oklch(0.975 0.008 240);
  --mco-fit-ink: oklch(0.27 0.055 258);
  --mco-fit-tape: oklch(0.87 0.15 94);
  --mco-fit-mark: oklch(0.58 0.2 27);

  --mco-fit-muted: color-mix(in oklch, var(--mco-fit-ink) 58%, var(--mco-fit-bg));
  --mco-fit-line: color-mix(in oklch, var(--mco-fit-ink) 13%, transparent);
  --mco-fit-wash: color-mix(in oklch, var(--mco-fit-ink) 5%, transparent);
  --mco-fit-tapedk: color-mix(in oklch, var(--mco-fit-tape) 80%, oklch(0.45 0.1 70));
  --mco-fit-mono: ui-monospace, Menlo, "SF Mono", Consolas, monospace;
  --mco-fit-spring: linear(0, 0.009, 0.035 2.1%, 0.141 4.4%, 0.723 12.9%, 0.938 16.7%, 1.017 19.4%, 1.067, 1.099 24.3%, 1.104 26.4%, 1.098 28.7%, 1.045 34.9%, 1.009 41.2%, 0.993 47.6%, 0.995 59.1%, 1);
  --mco-fit-out: cubic-bezier(.2, .85, .25, 1);
  --mco-fit-px: 7px;

  container-type: inline-size;
  position: relative; box-sizing: border-box; width: 100%; min-height: 158px;
  display: grid; gap: 14px; align-content: start;
  padding: 16px;
  border-radius: 18px;
  background: var(--mco-fit-bg); color: var(--mco-fit-ink);
  box-shadow: inset 0 0 0 1px var(--mco-fit-line), 0 18px 40px -26px oklch(0.25 0.05 258 / .45);
  font: 400 13px/1.4 system-ui, -apple-system, "Segoe UI", sans-serif;
  -webkit-font-smoothing: antialiased;

  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(button) { font: inherit; color: inherit; background: none; border: 0; padding: 0; margin: 0; cursor: pointer; }
  & :where(p, h3) { margin: 0; }
  & :where(svg) { display: block; flex: none; fill: none; stroke: currentColor; stroke-width: 1.5; stroke-linecap: round; stroke-linejoin: round; }
  & :focus-visible { outline: 2px solid var(--mco-fit-ink); outline-offset: 2px; }
  & .mco-fit-sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }

  & .mco-fit-head { display: flex; align-items: flex-start; justify-content: space-between; gap: 10px; }
  & .mco-fit-eyebrow { font-size: 10.5px; font-weight: 700; letter-spacing: .12em; text-transform: uppercase; color: var(--mco-fit-muted); }
  & .mco-fit-title { margin-top: 2px; font-size: clamp(16px, 5.2cqi, 19px); font-weight: 700; letter-spacing: -.015em; text-wrap: balance; }

  & :is(.mco-fit-units, .mco-fit-pref) {
    display: inline-grid; grid-auto-flow: column; grid-auto-columns: 1fr; padding: 3px; border-radius: 10px; background: var(--mco-fit-wash); box-shadow: inset 0 0 0 1px var(--mco-fit-line);
    & [role="radio"] { position: relative; height: 26px; padding: 0 10px; border-radius: 7px; font-size: 12px; font-weight: 600; color: var(--mco-fit-muted); transition: color .2s, background-color .2s, box-shadow .2s; }
    & [role="radio"]:hover { color: var(--mco-fit-ink); }
    & [aria-checked="true"] { color: var(--mco-fit-ink); background: var(--mco-fit-bg); box-shadow: 0 1px 2px oklch(0.3 0.05 258 / .18), 0 0 0 1px var(--mco-fit-line); }
  }
  & .mco-fit-units [role="radio"] { font-family: var(--mco-fit-mono); padding: 0 9px; }
  & .mco-fit-pref { display: grid; }

  /* ---------- tapes ---------- */
  & .mco-fit-measure { display: grid; grid-template-columns: 54px minmax(0, 1fr); gap: 12px; align-items: center; }
  & .mco-fit-fig {
    width: 54px; height: auto; color: var(--mco-fit-ink);
    & .mco-fit-body { fill: var(--mco-fit-wash); stroke: color-mix(in oklch, var(--mco-fit-ink) 40%, transparent); stroke-width: 1.2; }
    & .mco-fit-line { stroke: color-mix(in oklch, var(--mco-fit-ink) 45%, transparent); stroke-dasharray: 2.5 2.5; transition: stroke .2s, stroke-width .2s; }
  }
  & .mco-fit-tapes { display: grid; gap: 10px; min-width: 0; }
  & .mco-fit-mlabel {
    display: flex; align-items: baseline; justify-content: space-between; margin-bottom: 5px;
    & span { font-size: 11px; font-weight: 700; letter-spacing: .1em; text-transform: uppercase; color: var(--mco-fit-muted); transition: color .2s; }
    & output { font: 650 14px/1 var(--mco-fit-mono); font-variant-numeric: tabular-nums; }
  }
  & .mco-fit-tape {
    position: relative; height: 40px; border-radius: 7px; overflow: hidden; cursor: grab; touch-action: pan-y; user-select: none;
    background: linear-gradient(to bottom, var(--mco-fit-tapedk), var(--mco-fit-tape) 18%, var(--mco-fit-tape) 82%, var(--mco-fit-tapedk));
    box-shadow: inset 0 0 0 1px oklch(0.4 0.08 75 / .25);
    -webkit-mask: linear-gradient(to right, transparent, #000 16%, #000 84%, transparent); mask: linear-gradient(to right, transparent, #000 16%, #000 84%, transparent);
    &:active { cursor: grabbing; }
    & input { position: absolute; inset: 0; width: 100%; height: 100%; margin: 0; opacity: 0; pointer-events: none; }
  }
  & .mco-fit-m:has(input:focus-visible) .mco-fit-tape { -webkit-mask: none; mask: none; outline: 2px solid var(--mco-fit-ink); outline-offset: 2px; }
  & .mco-fit-strip {
    position: absolute; top: 0; bottom: 0; left: 50%;
    width: calc(var(--len) * var(--mco-fit-px) + 1px);
    translate: calc((var(--min) - var(--v)) * var(--mco-fit-px)) 0;
    transition: translate .45s var(--mco-fit-spring);
    background:
      linear-gradient(90deg, var(--mco-fit-ink) 0 1.5px, transparent 1.5px) var(--offM, 0px) 0 / var(--major, 35px) 15px repeat-x,
      linear-gradient(90deg, var(--mco-fit-ink) 0 1px, transparent 1px) var(--offH, 17.5px) 0 / var(--major, 35px) 11px repeat-x,
      linear-gradient(90deg, color-mix(in oklch, var(--mco-fit-ink) 75%, transparent) 0 1px, transparent 1px) var(--offm, 0px) 0 / var(--minor, 7px) 7px repeat-x;
    & span { position: absolute; top: 17px; translate: -50% 0; font: 600 10px/1 var(--mco-fit-mono); color: var(--mco-fit-ink); font-variant-numeric: tabular-nums; }
  }
  & .mco-fit-tape.is-drag .mco-fit-strip { transition: none; }
  & .mco-fit-cursor {
    position: absolute; top: 0; bottom: 0; left: 50%; width: 2px; margin-left: -1px; background: var(--mco-fit-mark); pointer-events: none;
    &::before { content: ""; position: absolute; top: 0; left: 50%; width: 10px; height: 6px; translate: -50% 0; background: var(--mco-fit-mark); clip-path: polygon(0 0, 100% 0, 50% 100%); }
  }
  &:has([data-m="chest"] :is(.mco-fit-tape:hover, input:focus-visible)) [data-line="chest"],
  &:has([data-m="waist"] :is(.mco-fit-tape:hover, input:focus-visible)) [data-line="waist"] { stroke: var(--mco-fit-mark); stroke-width: 2.2; stroke-dasharray: none; }
  & .mco-fit-m:has(:is(.mco-fit-tape:hover, input:focus-visible)) .mco-fit-mlabel span { color: var(--mco-fit-mark); }

  /* ---------- verdict ---------- */
  & .mco-fit-result {
    display: grid; grid-template-columns: auto minmax(0, 1fr); align-items: center; gap: 14px;
    padding: 10px 14px 10px 10px; border-radius: 14px; background: var(--mco-fit-ink); color: var(--mco-fit-bg);
  }
  & .mco-fit-size {
    display: grid; place-items: center; min-width: 52px; height: 52px; padding: 0 8px; border-radius: 11px;
    background: var(--mco-fit-tape); color: var(--mco-fit-ink);
    font-size: 26px; font-weight: 800; letter-spacing: -.03em;
    &.is-swap { animation: mco-fit-in .45s var(--mco-fit-spring) both; }
  }
  & .mco-fit-verdict { font-size: 14px; font-weight: 650; letter-spacing: -.005em; text-wrap: balance; font-variant-numeric: tabular-nums; }
  & .mco-fit-note { margin-top: 2px; font-size: 12px; color: color-mix(in oklch, var(--mco-fit-bg) 70%, var(--mco-fit-ink)); text-wrap: pretty; }
  & .mco-fit-result[data-state="out"] {
    background: color-mix(in oklch, var(--mco-fit-mark) 12%, var(--mco-fit-bg)); color: var(--mco-fit-ink); box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--mco-fit-mark) 35%, transparent);
    & .mco-fit-size { background: var(--mco-fit-mark); color: var(--mco-fit-bg); font-size: 20px; }
    & .mco-fit-note { color: var(--mco-fit-muted); }
  }

  /* ---------- chart with a sliding row marker ---------- */
  & .mco-fit-chart { position: relative; }
  & .mco-fit-mark {
    position: absolute; left: -6px; right: -6px; top: 0; height: var(--h, 28px); border-radius: 8px;
    background: color-mix(in oklch, var(--mco-fit-tape) 45%, transparent); box-shadow: inset 0 0 0 1.5px var(--mco-fit-tapedk);
    translate: 0 var(--y, 0px); transition: translate .5s var(--mco-fit-spring), opacity .25s;
    &[hidden] { display: block; opacity: 0; }
  }
  & .mco-fit-table {
    position: relative; width: 100%; border-collapse: collapse; font-variant-numeric: tabular-nums;
    & th { padding: 0 0 6px; font-size: 10.5px; font-weight: 700; letter-spacing: .08em; text-transform: uppercase; color: var(--mco-fit-muted); text-align: left; border-bottom: 1px solid var(--mco-fit-line); }
    & td { height: 28px; padding: 0; font: 500 12px/1 var(--mco-fit-mono); border-bottom: 1px solid var(--mco-fit-line); }
    & tr:last-child td { border-bottom: 0; }
    & td:first-child { font: 750 13px/1 system-ui, -apple-system, sans-serif; width: 3.2em; }
    & :is(th, td):last-child { text-align: right; }
    & tr[data-rec] td:first-child { color: var(--mco-fit-ink); }
  }
  & .mco-fit-on {
    display: inline-flex; align-items: center; gap: 5px; font: 600 11.5px/1 system-ui, -apple-system, sans-serif;
    &::before { content: ""; width: 7px; height: 7px; border-radius: 50%; background: var(--c); }
    &[data-f="tight"] { --c: var(--mco-fit-mark); color: var(--mco-fit-mark); }
    &[data-f="close"] { --c: oklch(0.7 0.13 60); }
    &[data-f="regular"] { --c: oklch(0.6 0.12 150); }
    &[data-f="relaxed"] { --c: oklch(0.62 0.1 230); }
    &[data-f="over"] { --c: var(--mco-fit-muted); color: var(--mco-fit-muted); }
  }

  & .mco-fit-cta {
    display: inline-flex; align-items: center; justify-content: center; gap: 8px; height: 42px; border-radius: 11px;
    background: var(--mco-fit-ink); color: var(--mco-fit-bg); font-size: 13.5px; font-weight: 650;
    transition: background-color .2s, translate .3s var(--mco-fit-out), opacity .2s;
    & svg { width: 16px; height: 16px; stroke-width: 2; animation: mco-fit-ok .4s var(--mco-fit-spring) both; }
    &:hover:not(:disabled) { translate: 0 -1px; background: color-mix(in oklch, var(--mco-fit-ink) 86%, var(--mco-fit-mark)); }
    &:disabled { opacity: .35; cursor: not-allowed; }
    &[data-done], &[data-done]:hover:not(:disabled) { background: oklch(0.5 0.11 152); translate: none; }
  }

  @container (max-width: 289px) {
    & .mco-fit-measure { grid-template-columns: minmax(0, 1fr); }
    & .mco-fit-fig { display: none; }
    & .mco-fit-result { gap: 10px; padding: 9px 12px 9px 9px; }
  }
  @container (max-width: 259px) {
    & .mco-fit-table th:nth-child(3), & .mco-fit-table td:nth-child(3) { display: none; }
  }
}

@media (prefers-reduced-motion: reduce) {
  .mco-fit {
    & .mco-fit-strip { transition: none; }
    & .mco-fit-mark { transition: opacity .2s; }
    & .mco-fit-size.is-swap, & .mco-fit-cta svg { animation: none; }
    & .mco-fit-cta:hover:not(:disabled) { translate: none; }
  }
}

