const $ = (s, el) => (el || root).querySelector(s);
const RM = matchMedia('(prefers-reduced-motion: reduce)');
const PX = 7, IN = 2.54;
/* body chart (cm) and the finished garment's chest, from which ease is measured */
const SIZES = [
  { s: 'XS', chest: [80, 86], waist: [66, 72], garment: 92 },
  { s: 'S', chest: [86, 92], waist: [72, 78], garment: 98 },
  { s: 'M', chest: [92, 98], waist: [78, 84], garment: 104 },
  { s: 'L', chest: [98, 104], waist: [84, 90], garment: 110 },
  { s: 'XL', chest: [104, 110], waist: [90, 96], garment: 116 }
];
const FIT = (e) => e < 2 ? ['tight', 'Too tight'] : e < 6 ? ['close', 'Close'] : e < 10 ? ['regular', 'Regular'] : e < 16 ? ['relaxed', 'Relaxed'] : ['over', 'Oversized'];
let unit = 'cm', target = 8, rec = null, chosen = null;

const tapes = {};
root.querySelectorAll('.mco-fit-m').forEach((m) => {
  const input = $('input', m);
  tapes[m.dataset.m] = { m, input, tape: $('[data-tape]', m), strip: $('[data-strip]', m), read: $('[data-read]', m), min: +input.min, max: +input.max, v: +input.value };
});
const rowsEl = $('[data-rows]'), mark = $('[data-mark]'), sizeEl = $('[data-size]'), cta = $('[data-cta]');
rowsEl.innerHTML = SIZES.map((z) => '<tr data-s="' + z.s + '"><td>' + z.s + '</td><td data-c></td><td data-w></td><td><span class="mco-fit-on"></span></td></tr>').join('');
const rows = Array.from(rowsEl.children);

const q = (v) => Math.round(v * 2) / 2;
const show = (cm) => unit === 'cm' ? (Number.isInteger(cm) ? cm : cm.toFixed(1)) + ' cm' : (cm / IN).toFixed(1) + ' in';
const range = (r) => unit === 'cm' ? r[0] + '–' + r[1] : (r[0] / IN).toFixed(1) + '–' + (r[1] / IN).toFixed(1);
const easeTxt = (e) => unit === 'cm' ? e + ' cm' : (e / IN).toFixed(1) + ' in';

/* ticks and labels for the current unit; the strip always moves in cm, so only the marks change */
function drawTicks(t) {
  const len = t.max - t.min;
  let html = '', major, minor, offM, offH, offm;
  if (unit === 'cm') {
    major = 5 * PX; minor = PX; offM = 0; offH = 2.5 * PX; offm = 0;
    for (let c = t.min; c <= t.max; c += 5) html += '<span style="left:' + (c - t.min) * PX + 'px">' + c + '</span>';
  } else {
    const pin = IN * PX, startIn = t.min / IN;
    major = pin; minor = pin / 4;
    offM = (Math.ceil(startIn) - startIn) * pin;
    offH = (offM + pin / 2) % pin;
    offm = (Math.ceil(startIn * 4) / 4 - startIn) * pin;
    for (let i = Math.ceil(startIn); i <= t.max / IN; i++) if (i % 2 === 0) html += '<span style="left:' + ((i - startIn) * pin).toFixed(2) + 'px">' + i + '</span>';
  }
  const s = t.strip.style;
  s.setProperty('--len', len);
  s.setProperty('--major', major + 'px'); s.setProperty('--minor', minor + 'px');
  s.setProperty('--offM', offM + 'px'); s.setProperty('--offH', offH + 'px'); s.setProperty('--offm', offm + 'px');
  t.strip.innerHTML = html;
}

function setV(t, v, live) {
  v = Math.max(t.min, Math.min(t.max, v));
  t.v = v;
  t.tape.style.setProperty('--v', v.toFixed(3));
  const sv = q(v);
  t.input.value = sv;
  t.read.textContent = show(sv);
  t.input.setAttribute('aria-valuetext', sv + ' centimetres, ' + (sv / IN).toFixed(1) + ' inches');
  recompute();
}

function recompute() {
  const chest = q(tapes.chest.v), waist = q(tapes.waist.v);
  rows.forEach((tr, i) => {
    const z = SIZES[i], e = z.garment - chest, f = FIT(e);
    $('[data-c]', tr).textContent = range(z.chest);
    $('[data-w]', tr).textContent = range(z.waist);
    const on = $('.mco-fit-on', tr);
    on.dataset.f = f[0];
    on.textContent = f[1];
  });
  /* closest ease to the preference, never tighter than 2 cm; then size up if the waist needs it */
  let best = -1, bd = 1e9;
  SIZES.forEach((z, i) => { const e = z.garment - chest; if (e < 2) return; const d = Math.abs(e - target) + (e < target ? .01 : 0); if (d < bd) { bd = d; best = i; } });
  let note = '', state = 'ok';
  if (best < 0) {
    state = 'out';
  } else {
    const byWaist = SIZES.findIndex((z) => waist <= z.waist[1]);
    if (byWaist < 0) { state = 'out'; best = -1; }
    else if (byWaist > best) { note = 'Sized up from ' + SIZES[best].s + ' so the waist isn’t snug.'; best = byWaist; }
    else note = waist < SIZES[best].waist[0] ? 'Waist is below ' + SIZES[best].s + '’s range — the rib hem will sit loose.' : 'Your waist sits inside ' + SIZES[best].s + '’s range.';
  }
  const res = $('[data-result]');
  res.dataset.state = state;
  const prev = rec;
  rec = best < 0 ? null : SIZES[best].s;
  if (state === 'out') {
    sizeEl.textContent = '—';
    $('[data-verdict]').textContent = chest > 114 || waist > 96 ? 'Above our size range' : 'Outside our size chart';
    $('[data-note]').textContent = 'XL measures ' + show(SIZES[4].garment) + ' at the chest. Our made-to-measure service goes up to ' + show(140) + '.';
  } else {
    const e = SIZES[best].garment - chest, f = FIT(e);
    sizeEl.textContent = rec;
    $('[data-verdict]').textContent = f[1] + ' fit · ' + easeTxt(e) + ' of ease';
    $('[data-note]').textContent = note;
  }
  if (prev !== rec && !RM.matches) { sizeEl.classList.remove('is-swap'); void sizeEl.offsetWidth; sizeEl.classList.add('is-swap'); }
  rows.forEach((tr) => tr.toggleAttribute('data-rec', tr.dataset.s === rec));
  const tr = rows.find((r) => r.dataset.s === rec);
  mark.hidden = !tr;
  if (tr) { mark.style.setProperty('--y', tr.offsetTop + 'px'); mark.style.setProperty('--h', tr.offsetHeight + 'px'); }
  if (chosen !== rec) { cta.removeAttribute('data-done'); }
  cta.disabled = !rec;
  if (!cta.hasAttribute('data-done')) cta.textContent = rec ? 'Use size ' + rec : 'No size fits these measurements';
}

/* drag the tape like a real one: direct while held, then a short glide with friction */
Object.values(tapes).forEach((t) => {
  let x0 = 0, v0 = 0, last = 0, lastT = 0, vel = 0, raf = 0, dragging = false;
  t.tape.addEventListener('pointerdown', (e) => {
    if (e.button !== 0) return;
    cancelAnimationFrame(raf);
    dragging = true; x0 = e.clientX; v0 = t.v; last = e.clientX; lastT = e.timeStamp; vel = 0;
    t.tape.setPointerCapture(e.pointerId);
    t.tape.classList.add('is-drag');
    t.input.focus({ preventScroll: true });
    e.preventDefault();
  });
  t.tape.addEventListener('pointermove', (e) => {
    if (!dragging) return;
    const dt = Math.max(1, e.timeStamp - lastT);
    vel = .7 * vel + .3 * (-(e.clientX - last) / PX / dt);
    last = e.clientX; lastT = e.timeStamp;
    setV(t, v0 - (e.clientX - x0) / PX, true);
  });
  const end = () => {
    if (!dragging) return;
    dragging = false;
    if (RM.matches || Math.abs(vel) < .004) { t.tape.classList.remove('is-drag'); setV(t, q(t.v)); return; }
    let prevT = performance.now();
    const glide = (now) => {
      if (!root.isConnected) return;
      const dt = Math.min(32, now - prevT); prevT = now;
      vel *= Math.pow(.9, dt / 16);
      setV(t, t.v + vel * dt, true);
      if (Math.abs(vel) > .002 && t.v > t.min && t.v < t.max) raf = requestAnimationFrame(glide);
      else { t.tape.classList.remove('is-drag'); setV(t, q(t.v)); }
    };
    raf = requestAnimationFrame(glide);
  };
  t.tape.addEventListener('pointerup', end);
  t.tape.addEventListener('pointercancel', end);
  t.input.addEventListener('input', () => setV(t, +t.input.value));
});

function radios(group, cb) {
  const btns = Array.from(group.querySelectorAll('[role="radio"]'));
  const pick = (b, focus) => { btns.forEach((x) => { const on = x === b; x.setAttribute('aria-checked', String(on)); x.tabIndex = on ? 0 : -1; }); if (focus) b.focus(); cb(b); };
  group.addEventListener('click', (e) => { const b = e.target.closest('[role="radio"]'); if (b) pick(b); });
  group.addEventListener('keydown', (e) => {
    const i = btns.indexOf(e.target), d = { ArrowRight: 1, ArrowDown: 1, ArrowLeft: -1, ArrowUp: -1 }[e.key];
    if (i < 0 || !d) return;
    e.preventDefault();
    pick(btns[(i + d + btns.length) % btns.length], true);
  });
}
radios($('[data-units]'), (b) => { unit = b.dataset.u; Object.values(tapes).forEach((t) => { drawTicks(t); setV(t, t.v); }); });
radios($('[data-pref]'), (b) => { target = +b.dataset.p; recompute(); });

cta.addEventListener('click', () => {
  if (!rec) return;
  chosen = rec;
  cta.setAttribute('data-done', '');
  cta.innerHTML = '<svg viewBox="0 0 16 16" aria-hidden="true"><path d="M3.5 8.5l3 3 6-7"/></svg>Size ' + rec + ' selected';
});

/* the row marker reads offsets, so re-place it when the card is resized */
const ro = new ResizeObserver(() => { if (!root.isConnected) { ro.disconnect(); return; } recompute(); });
ro.observe(root);
Object.values(tapes).forEach((t) => { drawTicks(t); setV(t, t.v); });

