@keyframes mco-ship-spin { to { rotate: 360deg; } }
@keyframes mco-ship-shake { 20%, 60% { translate: -4px 0; } 40%, 80% { translate: 4px 0; } }
@keyframes mco-ship-blink { 50% { opacity: .35; } }

.mco-ship {
  /* re-theme with these four */
  --mco-ship-bg: oklch(0.225 0.03 210);
  --mco-ship-ink: oklch(0.95 0.015 195);
  --mco-ship-accent: oklch(0.77 0.16 58);
  --mco-ship-bad: oklch(0.72 0.15 28);

  --mco-ship-muted: color-mix(in oklch, var(--mco-ship-ink) 60%, var(--mco-ship-bg));
  --mco-ship-faint: color-mix(in oklch, var(--mco-ship-ink) 32%, var(--mco-ship-bg));
  --mco-ship-line: color-mix(in oklch, var(--mco-ship-ink) 11%, transparent);
  --mco-ship-raise: color-mix(in oklch, var(--mco-ship-ink) 5%, transparent);
  --mco-ship-glow: color-mix(in oklch, var(--mco-ship-accent) 18%, transparent);
  --mco-ship-out: cubic-bezier(.2, .9, .25, 1);
  --mco-ship-spring: linear(0, 0.009, 0.035 2.1%, 0.141 4.4%, 0.723 12.9%, 0.938 16.7%, 1.017 19.4%, 1.077 22.4%, 1.101 25.5%, 1.096 28.9%, 1.065 34.1%, 1.016 42.2%, 0.997 49.1%, 0.991 56.4%, 1.001 76.4%, 1);

  container-type: inline-size;
  position: relative; box-sizing: border-box; width: 100%; min-height: 158px;
  display: grid; gap: 12px; align-content: start;
  padding: 16px;
  border-radius: 18px; border: 1px solid var(--mco-ship-line);
  background:
    radial-gradient(120% 80% at 100% 0%, color-mix(in oklch, var(--mco-ship-accent) 10%, transparent), transparent 60%),
    var(--mco-ship-bg);
  color: var(--mco-ship-ink);
  font: 400 13px/1.4 system-ui, -apple-system, "Segoe UI", sans-serif;
  -webkit-font-smoothing: antialiased;

  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(button, input) { font: inherit; color: inherit; background: none; border: 0; padding: 0; margin: 0; }
  & :where(button) { cursor: pointer; }
  & :where(p) { margin: 0; }
  & :where(svg) { display: block; flex: none; fill: none; stroke: currentColor; stroke-width: 1.5; stroke-linecap: round; stroke-linejoin: round; }
  & :focus-visible { outline: 2px solid var(--mco-ship-accent); outline-offset: 2px; }
  & .mco-ship-sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }

  /* ---------- postcode ---------- */
  & .mco-ship-head { display: grid; grid-template-columns: minmax(0, 1fr) auto; grid-template-areas: "eye eye" "form form" "where where"; gap: 6px 10px; }
  & .mco-ship-eyebrow { grid-area: eye; font-size: 10.5px; font-weight: 700; letter-spacing: .12em; text-transform: uppercase; color: var(--mco-ship-accent); }
  & .mco-ship-zip {
    grid-area: form; display: grid; grid-template-columns: minmax(0, 1fr) auto; height: 40px; border-radius: 11px;
    background: var(--mco-ship-raise); box-shadow: inset 0 0 0 1px var(--mco-ship-line); transition: box-shadow .2s;
    &:focus-within { box-shadow: inset 0 0 0 1.5px var(--mco-ship-accent), 0 0 0 4px var(--mco-ship-glow); }
    &:has([aria-invalid="true"]) { box-shadow: inset 0 0 0 1.5px var(--mco-ship-bad); }
    &.is-shake { animation: mco-ship-shake .36s; }
  }
  & .mco-ship-in {
    display: flex; align-items: center; gap: 9px; padding-left: 12px; min-width: 0; cursor: text;
    & svg { width: 16px; height: 16px; color: var(--mco-ship-accent); }
    & input { width: 100%; height: 100%; outline: none; font: 650 15px/1 ui-monospace, Menlo, monospace; letter-spacing: .06em; text-transform: uppercase; }
  }
  & .mco-ship-check {
    position: relative; margin: 4px; padding: 0 13px; border-radius: 8px; font-size: 12.5px; font-weight: 650; color: var(--mco-ship-bg); background: var(--mco-ship-ink);
    transition: background-color .2s, scale .2s;
    &:hover { background: var(--mco-ship-accent); }
    &:active { scale: .96; }
    &[aria-busy="true"] { cursor: progress;
      & span { opacity: 0; }
      &::after { content: ""; position: absolute; inset: 0; margin: auto; width: 14px; height: 14px; border-radius: 50%; border: 2px solid color-mix(in oklch, var(--mco-ship-bg) 25%, transparent); border-top-color: var(--mco-ship-bg); animation: mco-ship-spin .7s linear infinite; }
    }
  }
  & .mco-ship-where {
    grid-area: where; min-height: 18px; font-size: 12px; color: var(--mco-ship-muted); text-wrap: pretty;
    & b { color: var(--mco-ship-ink); font-weight: 650; }
    &[data-tone="err"] { color: var(--mco-ship-bad); }
  }

  /* ---------- cutoff countdown ---------- */
  & .mco-ship-cut {
    display: flex; align-items: center; gap: 10px; padding: 10px 12px; border-radius: 12px;
    background: var(--mco-ship-glow); box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--mco-ship-accent) 30%, transparent);
    & svg { width: 18px; height: 18px; color: var(--mco-ship-accent); }
    & p { font-size: 12.5px; line-height: 1.35; text-wrap: pretty; }
    & time { font: 700 13px/1 ui-monospace, Menlo, monospace; font-variant-numeric: tabular-nums; color: var(--mco-ship-accent); white-space: nowrap; }
    & b { font-weight: 650; }
    &[data-late] { background: var(--mco-ship-raise); box-shadow: inset 0 0 0 1px var(--mco-ship-line);
      & svg, & time { color: var(--mco-ship-muted); }
    }
  }
  & .mco-ship-colon { animation: mco-ship-blink 1s steps(1) infinite; }

  /* ---------- 14-day strip; the arrival window is one bar re-clipped per option ---------- */
  & .mco-ship-cal { display: grid; gap: 6px; }
  & .mco-ship-calhead {
    display: flex; justify-content: space-between; align-items: baseline; font-size: 11px; color: var(--mco-ship-muted);
    & > span:first-child { font-weight: 700; letter-spacing: .08em; text-transform: uppercase; color: var(--mco-ship-ink); }
  }
  & .mco-ship-legend { display: inline-flex; align-items: center; gap: 5px;
    & i { display: inline-block; width: 10px; height: 4px; border-radius: 2px; margin-left: 6px; }
    & .is-disp { width: 6px; height: 6px; border-radius: 50%; background: var(--mco-ship-ink); }
    & .is-win { background: var(--mco-ship-accent); }
  }
  & .mco-ship-days {
    --mco-ship-n: 14;
    position: relative; display: grid; grid-template-columns: repeat(var(--mco-ship-n), minmax(0, 1fr)); padding-bottom: 10px; overflow: hidden;
  }
  & .mco-ship-day {
    position: relative; z-index: 1; display: grid; justify-items: center; gap: 1px; padding: 5px 0 6px; font-variant-numeric: tabular-nums;
    & span { font-size: 9.5px; font-weight: 600; letter-spacing: .04em; color: var(--mco-ship-muted); text-transform: uppercase; }
    & b { font-size: clamp(11px, 3.6cqi, 13px); font-weight: 650; }
    &.is-off { & b, & span { color: var(--mco-ship-faint); } }
    &.is-today b { color: var(--mco-ship-accent); }
    &.is-today::before { content: ""; position: absolute; inset: 1px 8%; border-radius: 8px; box-shadow: inset 0 0 0 1px var(--mco-ship-faint); }
    &.is-in { & b, & span { color: var(--mco-ship-bg); } }
    &.is-first::after { content: ""; position: absolute; left: -.5px; top: 3px; bottom: 3px; width: 1px; background: var(--mco-ship-faint); }
    & b, & span { transition: color .35s; }
  }
  & .mco-ship-win {
    position: absolute; inset: 0 0 10px 0; border-radius: 9px; background: var(--mco-ship-accent);
    box-shadow: 0 6px 18px -6px color-mix(in oklch, var(--mco-ship-accent) 70%, transparent);
    clip-path: inset(0 max(0%, calc((var(--mco-ship-n) - var(--to, 2)) / var(--mco-ship-n) * 100%)) 0 calc(var(--from, 1) / var(--mco-ship-n) * 100%) round 9px);
    transition: clip-path .6s var(--mco-ship-out), opacity .3s;
  }
  & .mco-ship-days[data-none] .mco-ship-win { opacity: 0; }
  & .mco-ship-disp {
    position: absolute; bottom: 0; left: calc((var(--d, 0) + .5) / var(--mco-ship-n) * 100%); width: 6px; height: 6px; margin-left: -3px; border-radius: 50%; background: var(--mco-ship-ink);
    transition: left .5s var(--mco-ship-spring);
  }

  /* ---------- options ---------- */
  & .mco-ship-opts { display: grid; gap: 6px; }
  & .mco-ship-opt {
    position: relative; display: grid; grid-template-columns: 30px minmax(0, 1fr) auto; grid-template-areas: "ico name price" "ico when price"; align-items: center; column-gap: 10px;
    width: 100%; padding: 8px 12px 8px 8px; border-radius: 12px; text-align: left;
    box-shadow: inset 0 0 0 1px var(--mco-ship-line); transition: box-shadow .2s, background-color .2s;
    &:hover:not([aria-disabled="true"]) { background: var(--mco-ship-raise); }
    &[aria-checked="true"] { background: var(--mco-ship-raise); box-shadow: inset 0 0 0 1.5px var(--mco-ship-accent); }
    &[aria-disabled="true"] { cursor: not-allowed; opacity: .5; }
    & .mco-ship-ico { grid-area: ico; display: grid; place-items: center; width: 30px; height: 30px; border-radius: 9px; background: var(--mco-ship-raise); color: var(--mco-ship-muted); transition: background-color .2s, color .2s; }
    & .mco-ship-ico svg { width: 17px; height: 17px; }
    &[aria-checked="true"] .mco-ship-ico { background: var(--mco-ship-accent); color: var(--mco-ship-bg); }
    & .mco-ship-name { grid-area: name; font-size: 13px; font-weight: 650; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
    & .mco-ship-name small { font-size: 11.5px; font-weight: 450; color: var(--mco-ship-muted); }
    & .mco-ship-when { grid-area: when; font-size: 12px; color: var(--mco-ship-muted); font-variant-numeric: tabular-nums; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
    &[aria-checked="true"] .mco-ship-when { color: var(--mco-ship-ink); }
    & .mco-ship-price { grid-area: price; text-align: right; font: 650 12.5px/1.2 ui-monospace, Menlo, monospace; font-variant-numeric: tabular-nums; }
    & .mco-ship-price s { display: block; font-weight: 400; font-size: 10.5px; color: var(--mco-ship-faint); }
    & .mco-ship-price .is-free { color: var(--mco-ship-accent); letter-spacing: .04em; }
  }

  @container (max-width: 300px) {
    & .mco-ship-days { --mco-ship-n: 10; }
    & .mco-ship-day[data-i="10"], & .mco-ship-day[data-i="10"] ~ .mco-ship-day { display: none; }
    & .mco-ship-legend { display: none; }
    & .mco-ship-day span { font-size: 8.5px; }
    & .mco-ship-opt { grid-template-columns: 26px minmax(0, 1fr) auto; column-gap: 8px; padding: 7px 10px 7px 7px;
      & .mco-ship-ico { width: 26px; height: 26px; }
      & .mco-ship-name small { display: none; }
    }
  }
}

@media (prefers-reduced-motion: reduce) {
  .mco-ship {
    & .mco-ship-win { transition: opacity .2s; }
    & .mco-ship-disp { transition: none; }
    & .mco-ship-colon { animation: none; }
    & .mco-ship-zip.is-shake { animation: none; }
    & .mco-ship-check[aria-busy="true"]::after { animation-duration: 2s; }
  }
}

js:
const $ = (s, el) => (el || root).querySelector(s);
const RM = matchMedia('(prefers-reduced-motion: reduce)');
const DAY = 864e5, BAG = 6400, FREE_OVER = 5000;
const ICON = {
  std: '<svg viewBox="0 0 20 20" aria-hidden="true"><path d="M2 5.5h10v8H2zM12 8h3.2l2.8 3v2.5h-6"/><circle cx="5.5" cy="14.5" r="1.6"/><circle cx="14.5" cy="14.5" r="1.6"/></svg>',
  exp: '<svg viewBox="0 0 20 20" aria-hidden="true"><path d="M11.2 2 4.5 11h5l-1 7 6.8-9.2h-5z"/></svg>',
  eve: '<svg viewBox="0 0 20 20" aria-hidden="true"><path d="M15.8 12.6A6.6 6.6 0 0 1 7.4 4.2a6.6 6.6 0 1 0 8.4 8.4z"/></svg>',
  pick: '<svg viewBox="0 0 20 20" aria-hidden="true"><path d="M3 8.2 10 4l7 4.2V17H3z"/><path d="M7.5 17v-5h5v5"/></svg>'
};
/* transit in delivery days after dispatch, per zone; null = not offered */
const ZONES = {
  1: { label: 'next-day zone', t: { std: [1, 2], exp: [1, 1], eve: [1, 1], pick: [1, 2] } },
  2: { label: 'standard zone', t: { std: [2, 3], exp: [1, 1], eve: [1, 1], pick: [2, 3] } },
  3: { label: 'northern zone', t: { std: [2, 3], exp: [2, 2], eve: null, pick: [2, 4] } },
  4: { label: 'Wadden island', t: { std: [3, 5], exp: null, eve: null, pick: [3, 4] } }
};
const OPTS = [
  { k: 'std', name: 'Standard', sub: 'tracked', cut: 16, price: 495, free: true, sat: true },
  { k: 'exp', name: 'Express', sub: 'before 12:00', cut: 15, price: 895, sat: true },
  { k: 'eve', name: 'Evening', sub: '18:00–22:00', cut: 13, price: 595, sat: false },
  { k: 'pick', name: 'Pickup point', sub: '1,240 lockers', cut: 16, price: 0, sat: true }
];
const PLACES = { 10: 'Amsterdam', 11: 'Amsterdam', 25: 'The Hague', 30: 'Rotterdam', 35: 'Utrecht', 20: 'Haarlem', 23: 'Leiden', 56: 'Eindhoven', 65: 'Nijmegen', 68: 'Arnhem', 75: 'Enschede', 80: 'Zwolle', 97: 'Groningen', 89: 'Leeuwarden', 48: 'Breda', 62: 'Maastricht' };
const fShort = new Intl.DateTimeFormat('en-GB', { weekday: 'short', day: 'numeric' });
const fLong = new Intl.DateTimeFormat('en-GB', { weekday: 'short', day: 'numeric', month: 'short' });
const fMon = new Intl.DateTimeFormat('en-GB', { month: 'long' });
const fMonS = new Intl.DateTimeFormat('en-GB', { month: 'short' });
const eur = (c) => '€' + (c / 100).toFixed(2);

const form = $('[data-form]'), zip = $('[data-zip]'), check = $('[data-check]'), where = $('[data-where]');
const daysEl = $('[data-days]'), win = $('[data-win]'), disp = $('[data-disp]'), optsEl = $('[data-opts]');
const leftEl = $('[data-left]'), cutTxt = $('[data-cuttxt]'), cutFor = $('[data-cutfor]'), cutBox = $('[data-cut]');
let zone = 1, sel = 'std', origin = 0;

const midnight = (t) => { const d = new Date(t); d.setHours(0, 0, 0, 0); return d.getTime(); };
const addDays = (t, n) => { const d = new Date(t); d.setDate(d.getDate() + n); return d.getTime(); };
const isWeekday = (t) => { const w = new Date(t).getDay(); return w > 0 && w < 6; };

/* first cutoff still ahead of now on a dispatch (week)day */
function nextCutoff(o, now) {
  let d = midnight(now);
  for (let i = 0; i < 10; i++, d = addDays(d, 1)) {
    if (!isWeekday(d)) continue;
    const c = new Date(d); c.setHours(o.cut, 0, 0, 0);
    if (c.getTime() > now) return { dispatch: d, cutoff: c.getTime() };
  }
}
function addDelivery(from, n, sat) {
  let d = from;
  while (n > 0) { d = addDays(d, 1); const w = new Date(d).getDay(); if (w !== 0 && (sat || w !== 6)) n--; }
  return d;
}
function plan(o, now) {
  const tr = ZONES[zone].t[o.k];
  if (!tr) return null;
  const c = nextCutoff(o, now);
  return { ...c, from: addDelivery(c.dispatch, tr[0], o.sat), to: addDelivery(c.dispatch, tr[1], o.sat) };
}
const range = (p) => p.from === p.to ? fLong.format(p.from) : (new Date(p.from).getMonth() === new Date(p.to).getMonth() ? fShort.format(p.from) + ' – ' + fLong.format(p.to) : fLong.format(p.from) + ' – ' + fLong.format(p.to));
const priceOf = (o) => o.free && BAG >= FREE_OVER ? 0 : o.price;

function buildDays() {
  origin = midnight(Date.now());
  daysEl.querySelectorAll('.mco-ship-day').forEach((n) => n.remove());
  let html = '';
  for (let i = 0; i < 14; i++) {
    const t = addDays(origin, i), d = new Date(t);
    const first = i > 0 && d.getDate() === 1;
    html += '<span class="mco-ship-day' + (d.getDay() === 0 ? ' is-off' : '') + (i === 0 ? ' is-today' : '') + (first ? ' is-first' : '') + '" data-i="' + i + '" data-mon="' + fMonS.format(t) + '"><span>' + 'SMTWTFS'[d.getDay()] + '</span><b>' + d.getDate() + '</b></span>';
  }
  daysEl.insertAdjacentHTML('beforeend', html);
  const last = new Date(addDays(origin, 13));
  $('[data-month]').textContent = fMon.format(origin) + (last.getMonth() !== new Date(origin).getMonth() ? ' – ' + fMon.format(last) : '');
}

function renderOpts() {
  const now = Date.now();
  optsEl.innerHTML = OPTS.map((o) => {
    const p = plan(o, now), pr = priceOf(o);
    const dis = !p;
    return '<button type="button" role="radio" class="mco-ship-opt" data-k="' + o.k + '" aria-checked="' + (o.k === sel) + '" tabindex="' + (o.k === sel ? 0 : -1) + '"' + (dis ? ' aria-disabled="true"' : '') + '>' +
      '<span class="mco-ship-ico">' + ICON[o.k] + '</span>' +
      '<span class="mco-ship-name">' + o.name + ' <small>' + o.sub + '</small></span>' +
      '<span class="mco-ship-when">' + (dis ? 'Not offered to ' + (zone === 4 ? 'the islands' : 'this zone') : range(p)) + '</span>' +
      '<span class="mco-ship-price">' + (dis ? '—' : pr === 0 ? (o.price ? '<s>' + eur(o.price) + '</s>' : '') + '<span class="is-free">FREE</span>' : eur(pr)) + '</span></button>';
  }).join('');
}

function paint() {
  const now = Date.now();
  if (midnight(now) !== origin) buildDays();
  const o = OPTS.find((x) => x.k === sel), p = plan(o, now);
  const idx = (t) => Math.round((midnight(t) - origin) / DAY);
  if (!p) { daysEl.setAttribute('data-none', ''); return; }
  daysEl.removeAttribute('data-none');
  const a = idx(p.from), b = idx(p.to), d = idx(p.dispatch);
  win.style.setProperty('--from', Math.max(0, a));
  win.style.setProperty('--to', Math.min(14, b + 1));
  disp.style.setProperty('--d', d);
  daysEl.querySelectorAll('.mco-ship-day').forEach((n) => { const i = +n.dataset.i; n.classList.toggle('is-in', i >= a && i <= b); });
  tick();
}

function tick() {
  const now = Date.now(), o = OPTS.find((x) => x.k === sel), p = plan(o, now);
  if (!p) return;
  let s = Math.max(0, Math.floor((p.cutoff - now) / 1000));
  const dd = Math.floor(s / 86400); s -= dd * 86400;
  const h = Math.floor(s / 3600); s -= h * 3600;
  const m = Math.floor(s / 60); s -= m * 60;
  const pad = (n) => String(n).padStart(2, '0');
  const today = midnight(now) === p.dispatch;
  leftEl.innerHTML = dd ? dd + 'd ' + h + 'h ' + pad(m) + 'm' : h + 'h ' + pad(m) + '<span class="mco-ship-colon">m</span> ' + pad(s) + 's';
  leftEl.dateTime = 'PT' + (dd * 24 + h) + 'H' + m + 'M';
  cutTxt.textContent = today ? 'Order within' : 'Next dispatch in';
  cutFor.innerHTML = 'to get it <b>' + range(p) + '</b>' + (today ? '' : ' — today’s ' + o.cut + ':00 cutoff has passed');
  cutBox.toggleAttribute('data-late', !today);
  if (p.cutoff - now < 1000) setTimeout(() => { if (root.isConnected) { renderOpts(); paint(); } }, 1100);
}

function select(k, focus) {
  const btn = optsEl.querySelector('[data-k="' + k + '"]');
  if (!btn || btn.getAttribute('aria-disabled') === 'true') return;
  sel = k;
  optsEl.querySelectorAll('[role="radio"]').forEach((b) => { const on = b === btn; b.setAttribute('aria-checked', String(on)); b.tabIndex = on ? 0 : -1; });
  if (focus) btn.focus();
  paint();
  const o = OPTS.find((x) => x.k === k), p = plan(o, Date.now());
  $('[data-announce]').textContent = o.name + ': arrives ' + range(p) + ', ' + (priceOf(o) ? eur(priceOf(o)) : 'free') + '.';
}

optsEl.addEventListener('click', (e) => { const b = e.target.closest('[role="radio"]'); if (b) select(b.dataset.k); });
optsEl.addEventListener('keydown', (e) => {
  const d = { ArrowDown: 1, ArrowRight: 1, ArrowUp: -1, ArrowLeft: -1 }[e.key];
  if (!d) return;
  e.preventDefault();
  const btns = Array.from(optsEl.querySelectorAll('[role="radio"]:not([aria-disabled="true"])'));
  const i = btns.indexOf(e.target.closest('[role="radio"]'));
  select(btns[(i + d + btns.length) % btns.length].dataset.k, true);
});

/* Dutch postcodes: 4 digits (no leading 0) + 2 letters, never SA, SD or SS */
function zoneOf(n) {
  if ((n >= 1790 && n <= 1797) || (n >= 8881 && n <= 8899) || (n >= 9161 && n <= 9166)) return 4;
  if (n < 4000) return 1;
  if (n < 8000) return 2;
  return 3;
}
let busy = false;
form.addEventListener('submit', (e) => {
  e.preventDefault();
  if (busy) return;
  const raw = zip.value.trim().toUpperCase().replace(/\s+/g, '');
  const m = /^([1-9]\d{3})([A-Z]{2})$/.exec(raw);
  if (!m || /^(SA|SD|SS)$/.test(m[2])) {
    zip.setAttribute('aria-invalid', 'true');
    where.dataset.tone = 'err';
    where.textContent = m ? m[2] + ' isn’t used in Dutch postcodes — check the letters.' : 'Use a Dutch postcode, like 1017 CT.';
    const f = $('.mco-ship-zip');
    if (!RM.matches) { f.classList.remove('is-shake'); void f.offsetWidth; f.classList.add('is-shake'); }
    return;
  }
  busy = true;
  zip.value = m[1] + ' ' + m[2];
  zip.removeAttribute('aria-invalid');
  check.setAttribute('aria-busy', 'true');
  where.dataset.tone = '';
  where.textContent = 'Looking up ' + zip.value + '…';
  setTimeout(() => {
    if (!root.isConnected) return;
    busy = false;
    check.removeAttribute('aria-busy');
    const n = +m[1];
    zone = zoneOf(n);
    const place = zone === 4 ? ({ 179: 'Texel', 889: 'Vlieland', 888: 'Terschelling', 916: 'Ameland' }[Math.floor(n / 10)] || 'Schiermonnikoog') : (PLACES[Math.floor(n / 100)] || 'Zone ' + zone);
    let note = '';
    if (!ZONES[zone].t[sel]) { note = ' · ' + OPTS.find((x) => x.k === sel).name + ' isn’t offered here, switched to Standard'; sel = 'std'; }
    where.innerHTML = '<b></b> · ' + ZONES[zone].label + '<span></span>';
    where.firstChild.textContent = place;
    where.lastChild.textContent = note;
    renderOpts();
    paint();
  }, 520);
});
zip.addEventListener('input', () => { if (zip.getAttribute('aria-invalid')) { zip.removeAttribute('aria-invalid'); where.dataset.tone = ''; where.textContent = 'Press Enter to update the estimate.'; } });

/* the countdown runs only while visible */
let visible = true;
const io = new IntersectionObserver((en) => { visible = en[0].isIntersecting; if (visible && root.isConnected) tick(); });
io.observe(root);
const iv = setInterval(() => {
  if (!root.isConnected) { clearInterval(iv); io.disconnect(); return; }
  if (!visible || document.hidden) return;
  if (midnight(Date.now()) !== origin) { renderOpts(); paint(); } else tick();
}, 1000);

buildDays();
renderOpts();
paint();

css:
@keyframes mco-heart-ring { 0% { scale: .25; opacity: .9; } 100% { scale: 1.65; opacity: 0; } }
@keyframes mco-heart-bit {
  0% { transform: rotate(var(--a)) translateY(-8px) scale(.2); opacity: 0; }
  18% { opacity: 1; }
  100% { transform: rotate(var(--a)) translateY(calc(var(--r) * -1)) scale(0); opacity: 1; }
}
@keyframes mco-heart-beat { 0% { scale: 1; } 25% { scale: .78; } 60% { scale: 1.22; } 100% { scale: 1; } }
@keyframes mco-heart-deflate { 0% { scale: 1; } 40% { scale: .86; } 100% { scale: 1; } }

.mco-heart {
  /* re-theme with these four */
  --mco-heart-bg: oklch(0.968 0.016 30);
  --mco-heart-ink: oklch(0.27 0.035 20);
  --mco-heart-love: oklch(0.6 0.215 20);
  --mco-heart-spark: oklch(0.83 0.13 78);

  --mco-heart-muted: color-mix(in oklch, var(--mco-heart-ink) 58%, var(--mco-heart-bg));
  --mco-heart-line: color-mix(in oklch, var(--mco-heart-ink) 12%, transparent);
  --mco-heart-wash: color-mix(in oklch, var(--mco-heart-ink) 5%, transparent);
  --mco-heart-card: oklch(1 0 0);
  --mco-heart-spring: linear(0, 0.009, 0.035 2.1%, 0.141 4.4%, 0.723 12.9%, 0.938 16.7%, 1.017 19.4%, 1.077 22.4%, 1.101 25.5%, 1.096 28.9%, 1.065 34.1%, 1.016 42.2%, 0.997 49.1%, 0.991 56.4%, 1.001 76.4%, 1);
  --mco-heart-out: cubic-bezier(.2, .9, .25, 1);

  container-type: inline-size;
  position: relative; box-sizing: border-box; width: 100%; max-width: 420px; min-height: 158px;
  display: grid; grid-template-areas: "media" "info"; gap: 12px;
  padding: 10px 10px 14px; border-radius: 20px;
  background: var(--mco-heart-bg); color: var(--mco-heart-ink);
  box-shadow: 0 1px 0 oklch(1 0 0 / .8) inset, 0 20px 44px -28px oklch(0.3 0.06 20 / .55);
  font: 400 13px/1.4 system-ui, -apple-system, "Segoe UI", sans-serif;
  -webkit-font-smoothing: antialiased;

  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(button, input) { font: inherit; color: inherit; background: none; border: 0; padding: 0; margin: 0; }
  & :where(button) { cursor: pointer; -webkit-tap-highlight-color: transparent; }
  & :where(p, h3) { margin: 0; }
  & :where(svg) { display: block; flex: none; fill: none; stroke: currentColor; stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; }
  & :focus-visible { outline: 2px solid var(--mco-heart-ink); outline-offset: 2px; }
  & .mco-heart-sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }

  /* ---------- media ---------- */
  & .mco-heart-media {
    grid-area: media; position: relative; aspect-ratio: 5 / 4; border-radius: 14px; overflow: hidden;
    display: grid; place-items: center;
    background: radial-gradient(42% 40% at 50% 60%, oklch(0.98 0.07 85 / .9), transparent), radial-gradient(90% 70% at 50% 100%, oklch(0.93 0.035 40), transparent 70%), oklch(0.95 0.025 35);
  }
  & .mco-heart-art { width: min(80%, 300px); height: auto; margin-top: 4%; overflow: visible;
    & :where(path, ellipse) { stroke: none; }
    & .mco-heart-cone { fill: oklch(0.98 0.06 88 / .35); }
    & .mco-heart-shadow { fill: oklch(0.4 0.05 30 / .2); }
    & .mco-heart-stem { fill: oklch(0.42 0.04 50); }
    & .mco-heart-base { fill: oklch(0.36 0.04 45); }
    & .mco-heart-shade { fill: oklch(0.7 0.115 48); }
    & .mco-heart-pleat { stroke: oklch(0.58 0.11 45); stroke-width: 1.3; fill: none; }
    & .mco-heart-rim { stroke: oklch(0.52 0.1 42); stroke-width: 2.4; fill: none; }
  }
  & .mco-heart-tag { position: absolute; left: 10px; top: 10px; padding: 4px 8px; border-radius: 6px; background: var(--mco-heart-card); font-size: 10px; font-weight: 700; letter-spacing: .1em; text-transform: uppercase; }

  /* ---------- the heart ---------- */
  & .mco-heart-btn {
    position: absolute; top: 8px; right: 8px; z-index: 3; width: 44px; height: 44px; border-radius: 50%;
    display: grid; place-items: center; background: var(--mco-heart-card); color: var(--mco-heart-ink);
    box-shadow: 0 6px 16px -8px oklch(0.3 0.06 20 / .55);
    transition: scale .5s var(--mco-heart-spring), color .2s;
    & > * { grid-area: 1 / 1; }
    &:hover { color: var(--mco-heart-love); }
    &:active { scale: .88; transition-duration: .12s; }
  }
  & .mco-heart-ico { width: 22px; height: 22px; overflow: visible;
    & .mco-heart-o { stroke-width: 1.7; }
    & .mco-heart-f { fill: var(--mco-heart-love); stroke: var(--mco-heart-love); stroke-width: 1.7;
      clip-path: circle(0% at 50% 60%); transition: clip-path .22s cubic-bezier(.5, 0, .75, 0); }
  }
  & .mco-heart-btn[aria-pressed="true"] {
    color: var(--mco-heart-love);
    & .mco-heart-f { clip-path: circle(75% at 50% 60%); transition: clip-path .42s var(--mco-heart-out) .06s; }
  }
  & .mco-heart-btn.is-pop .mco-heart-ico { animation: mco-heart-beat .6s var(--mco-heart-out); }
  & .mco-heart-btn.is-drop .mco-heart-ico { animation: mco-heart-deflate .35s var(--mco-heart-out); }
  & .mco-heart-ring { width: 44px; height: 44px; border-radius: 50%; border: 2px solid var(--mco-heart-love); opacity: 0; pointer-events: none; }
  & .mco-heart-btn.is-pop .mco-heart-ring { animation: mco-heart-ring .55s var(--mco-heart-out); }
  & .mco-heart-bits { position: relative; width: 0; height: 0; pointer-events: none;
    & i { position: absolute; left: -3.5px; top: -3.5px; width: 7px; height: 7px; border-radius: 50%; background: var(--mco-heart-love); opacity: 0;
      --a: calc(var(--i) * 36deg); --r: 37px; }
    & i:nth-child(even) { background: var(--mco-heart-spark); --r: 30px; width: 6px; height: 6px; left: -3px; top: -3px; }
    & i:nth-child(3n) { border-radius: 1px; }
  }
  & .mco-heart-btn.is-pop .mco-heart-bits i { animation: mco-heart-bit .62s cubic-bezier(.15, .7, .3, 1) both; animation-delay: calc(var(--i) * 8ms + 60ms); }

  /* ---------- toast ---------- */
  & .mco-heart-toast {
    position: absolute; left: 10px; right: 10px; bottom: 10px; z-index: 2;
    display: flex; align-items: center; gap: 8px; min-height: 40px; padding: 6px 6px 6px 12px; border-radius: 12px;
    background: var(--mco-heart-ink); color: var(--mco-heart-bg); font-size: 12.5px;
    box-shadow: 0 10px 24px -12px oklch(0.2 0.05 20 / .7);
    transition: opacity .25s, translate .4s var(--mco-heart-out), display .4s allow-discrete;
    @starting-style { opacity: 0; translate: 0 12px; }
    &:empty { display: none; }
    &.is-out { opacity: 0; translate: 0 12px; }
    & span { flex: 1; min-width: 0; text-wrap: pretty; line-height: 1.3; }
    & b { font-weight: 650; }
    & button { flex: none; height: 28px; padding: 0 10px; border-radius: 8px; font-size: 12px; font-weight: 650; color: var(--mco-heart-ink); background: var(--mco-heart-bg); transition: background-color .15s; }
    & button:hover { background: var(--mco-heart-card); }
    & .mco-heart-dot { width: 14px; height: 14px; border-radius: 50%; border: 2px solid color-mix(in oklch, var(--mco-heart-bg) 30%, transparent); border-top-color: var(--mco-heart-bg); animation: mco-heart-spin .7s linear infinite; flex: none; }
  }

  /* ---------- list menu ---------- */
  & .mco-heart-menu {
    position: absolute; top: 64px; right: 18px; z-index: 4; width: min(240px, calc(100% - 36px)); max-height: calc(100% - 76px); overflow: auto; overscroll-behavior: contain;
    padding: 6px; border-radius: 14px; background: var(--mco-heart-card); color: var(--mco-heart-ink);
    box-shadow: 0 0 0 1px var(--mco-heart-line), 0 18px 40px -16px oklch(0.25 0.05 20 / .55);
    transform-origin: 90% 0;
    transition: opacity .18s, scale .3s var(--mco-heart-spring), display .3s allow-discrete;
    @starting-style { opacity: 0; scale: .92; }
    &[hidden] { display: none; opacity: 0; scale: .96; }
  }
  & .mco-heart-mhead { padding: 4px 8px 6px; font-size: 10.5px; font-weight: 700; letter-spacing: .1em; text-transform: uppercase; color: var(--mco-heart-muted); }
  & .mco-heart-mi {
    display: grid; grid-template-columns: 18px minmax(0, 1fr) auto; align-items: center; gap: 9px; width: 100%; min-height: 34px; padding: 0 8px; border-radius: 9px; text-align: left; font-size: 13px;
    transition: background-color .12s;
    &:hover, &:focus-visible { background: var(--mco-heart-wash); }
    &:focus-visible { outline-offset: -2px; }
    & .mco-heart-box { width: 18px; height: 18px; border-radius: 6px; display: grid; place-items: center; box-shadow: inset 0 0 0 1.5px color-mix(in oklch, var(--mco-heart-ink) 30%, transparent); transition: background-color .2s, box-shadow .2s; }
    & .mco-heart-box svg { width: 12px; height: 12px; stroke-width: 2.2; color: var(--mco-heart-card); stroke-dasharray: 14; stroke-dashoffset: 14; transition: stroke-dashoffset .25s var(--mco-heart-out); }
    &[aria-checked="true"] .mco-heart-box { background: var(--mco-heart-love); box-shadow: none;
      & svg { stroke-dashoffset: 0; }
    }
    & .mco-heart-ln { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
    & .mco-heart-lc { font-size: 11.5px; color: var(--mco-heart-muted); font-variant-numeric: tabular-nums; }
    &[aria-disabled="true"] { cursor: not-allowed; color: var(--mco-heart-muted);
      & .mco-heart-box { box-shadow: inset 0 0 0 1.5px var(--mco-heart-line); }
      & .mco-heart-lc { color: var(--mco-heart-love); font-weight: 600; }
    }
    & > svg { width: 16px; height: 16px; justify-self: center; }
    &[hidden] { display: none; }
  }
  & .mco-heart-sep { display: block; height: 1px; margin: 5px 6px; background: var(--mco-heart-line); }
  & .mco-heart-newform {
    display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 6px; padding: 4px;
    &[hidden] { display: none; }
    & input { height: 32px; padding: 0 9px; border-radius: 8px; background: var(--mco-heart-wash); box-shadow: inset 0 0 0 1px var(--mco-heart-line); outline: none; font-size: 12.5px; }
    & input:focus { box-shadow: inset 0 0 0 1.5px var(--mco-heart-ink); }
    & input[aria-invalid="true"] { box-shadow: inset 0 0 0 1.5px var(--mco-heart-love); }
    & button { height: 32px; padding: 0 10px; border-radius: 8px; background: var(--mco-heart-ink); color: var(--mco-heart-card); font-size: 12px; font-weight: 650; }
    & .mco-heart-err { grid-column: 1 / -1; font-size: 11.5px; color: var(--mco-heart-love); text-wrap: pretty; }
    & .mco-heart-err:empty { display: none; }
  }

  /* ---------- info ---------- */
  & .mco-heart-info { grid-area: info; display: grid; grid-template-columns: minmax(0, 1fr) auto; grid-template-areas: "brand price" "name price" "meta meta"; column-gap: 12px; padding: 0 4px; }
  & .mco-heart-brand { grid-area: brand; font-size: 10.5px; font-weight: 700; letter-spacing: .12em; text-transform: uppercase; color: var(--mco-heart-muted); }
  & .mco-heart-name { grid-area: name; font-size: clamp(15px, 5cqi, 18px); font-weight: 680; letter-spacing: -.012em; line-height: 1.2; text-wrap: balance; }
  & .mco-heart-price { grid-area: price; align-self: center; font-size: clamp(15px, 5cqi, 18px); font-weight: 700; font-variant-numeric: tabular-nums; }
  & .mco-heart-meta { grid-area: meta; display: flex; align-items: center; justify-content: space-between; gap: 8px; margin-top: 10px; padding-top: 10px; border-top: 1px solid var(--mco-heart-line); }
  & .mco-heart-saves {
    display: flex; align-items: center; gap: 5px; font-size: 12.5px; color: var(--mco-heart-muted);
    & > svg { width: 14px; height: 14px; fill: var(--mco-heart-love); stroke: none; }
  }
  & .mco-heart-odo { display: inline-flex; font-weight: 700; color: var(--mco-heart-ink); font-variant-numeric: tabular-nums; line-height: 1.2em; height: 1.2em; overflow: hidden; }
  & .mco-heart-dig { display: block; height: 1.2em; overflow: hidden;
    & > span { display: grid; translate: 0 calc(var(--d) * -1.2em); transition: translate .75s var(--mco-heart-spring); transition-delay: calc(var(--p, 0) * 45ms); }
  }
  & .mco-heart-lists {
    display: inline-flex; align-items: center; gap: 4px; height: 30px; padding: 0 8px 0 11px; border-radius: 15px; font-size: 12px; font-weight: 600;
    box-shadow: inset 0 0 0 1px var(--mco-heart-line); transition: background-color .15s;
    & svg { width: 14px; height: 14px; transition: rotate .3s var(--mco-heart-out); }
    &:hover { background: var(--mco-heart-wash); }
    &[aria-expanded="true"] svg { rotate: 180deg; }
  }

  @container (min-width: 470px) {
    grid-template-columns: 1.1fr 1fr; grid-template-areas: "media info"; align-items: center;
  }
}
@keyframes mco-heart-spin { to { rotate: 360deg; } }

@media (prefers-reduced-motion: reduce) {
  .mco-heart {
    & .mco-heart-btn { transition: color .2s; }
    & .mco-heart-btn:active { scale: none; }
    & .mco-heart-btn.is-pop :is(.mco-heart-ico, .mco-heart-ring, .mco-heart-bits i), & .mco-heart-btn.is-drop .mco-heart-ico { animation: none; }
    & .mco-heart-ico .mco-heart-f, & .mco-heart-btn[aria-pressed="true"] .mco-heart-f { transition: clip-path .15s linear; }
    & .mco-heart-dig > span { transition: none; }
    & .mco-heart-toast, & .mco-heart-menu { transition: opacity .15s, display .15s allow-discrete; @starting-style { opacity: 0; translate: none; scale: none; } }
    & .mco-heart-toast .mco-heart-dot { animation-duration: 2s; }
  }
}

js:
const $ = (s, el) => (el || root).querySelector(s);
const RM = matchMedia('(prefers-reduced-motion: reduce)');
const heart = $('[data-heart]'), toast = $('[data-toast]'), menu = $('[data-menu]'), mlist = $('[data-mlist]');
const listsBtn = $('[data-lists]'), newBtn = $('[data-new]'), newForm = $('[data-newform]'), newName = $('[data-newname]'), newErr = $('[data-newerr]');
const odo = $('[data-odo]'), saveSr = $('[data-savesr]');
const BASE_SAVES = 2184, MAX = 30;
const CHECK = '<svg viewBox="0 0 16 16" aria-hidden="true"><path d="M3.5 8.4l3 3 6-6.8"/></svg>';
const esc = (s) => String(s).replace(/[&<>"]/g, (c) => '&#' + c.charCodeAt(0) + ';');
/* n = items already in the list, not counting this lamp */
const lists = [
  { id: 'wish', name: 'Wishlist', n: 11, on: false },
  { id: 'living', name: 'Living room refit', n: 7, on: false },
  { id: 'gifts', name: 'Gift ideas for Mum', n: 3, on: false },
  { id: 'studio', name: 'Studio', n: 30, on: false }
];
let toastT = 0, opener = null;
const saved = () => lists.some((l) => l.on);

/* ---------- odometer ---------- */
function renderOdo(n, animate) {
  const s = n.toLocaleString('en-US');
  const digits = odo.querySelectorAll('.mco-heart-dig');
  if (digits.length !== s.replace(/,/g, '').length) {
    odo.innerHTML = s.split('').map((ch) => ch === ',' ? '<span>,</span>' : '<span class="mco-heart-dig"><span>' + '0123456789'.split('').map((d) => '<span>' + d + '</span>').join('') + '</span></span>').join('');
  }
  const ds = Array.from(odo.querySelectorAll('.mco-heart-dig > span'));
  s.replace(/,/g, '').split('').forEach((ch, i) => {
    const el = ds[i];
    el.style.setProperty('--p', ds.length - 1 - i);
    if (!animate) { el.style.transition = 'none'; requestAnimationFrame(() => { if (!root.isConnected) return; el.style.transition = ''; }); }
    el.style.setProperty('--d', ch);
  });
  saveSr.textContent = s + (n === 1 ? ' person' : ' people') + ' saved this';
}

/* ---------- state paint ---------- */
function paint() {
  const on = saved();
  heart.setAttribute('aria-pressed', String(on));
  heart.setAttribute('aria-label', on ? 'Saved — remove Lumen Pleated Table Lamp from all lists' : 'Save Lumen Pleated Table Lamp to your wishlist');
  const inL = lists.filter((l) => l.on);
  $('[data-liststxt]').textContent = inL.length === 0 ? 'Add to a list' : inL.length === 1 ? 'In ' + inL[0].name : 'In ' + inL.length + ' lists';
  renderOdo(BASE_SAVES + (on ? 1 : 0), true);
  mlist.innerHTML = lists.map((l) => {
    const full = !l.on && l.n >= MAX;
    const count = l.n + (l.on ? 1 : 0);
    return '<button type="button" role="menuitemcheckbox" class="mco-heart-mi" data-l="' + l.id + '" aria-checked="' + l.on + '"' + (full ? ' aria-disabled="true"' : '') + ' tabindex="-1">' +
      '<span class="mco-heart-box">' + CHECK + '</span><span class="mco-heart-ln">' + esc(l.name) + '</span>' +
      '<span class="mco-heart-lc">' + (full ? 'Full · ' + MAX + '/' + MAX : count) + '</span></button>';
  }).join('');
}

function burst(on) {
  if (RM.matches) return;
  heart.classList.remove('is-pop', 'is-drop');
  void heart.offsetWidth;
  heart.classList.add(on ? 'is-pop' : 'is-drop');
}

function say(html, action, sticky) {
  clearTimeout(toastT);
  toast.classList.remove('is-out');
  toast.innerHTML = html;
  if (action) {
    const b = document.createElement('button');
    b.type = 'button'; b.textContent = action.label;
    b.addEventListener('click', action.run);
    toast.append(b);
  }
  if (!sticky) arm();
}
function hideToast() {
  if (!toast.innerHTML) return;
  toast.classList.add('is-out');
  toastT = setTimeout(() => { if (!root.isConnected) return; toast.innerHTML = ''; toast.classList.remove('is-out'); }, RM.matches ? 150 : 300);
}
function arm() { clearTimeout(toastT); toastT = setTimeout(() => { if (!root.isConnected) return; if (toast.matches(':hover, :focus-within')) arm(); else hideToast(); }, 4200); }

/* optimistic save: the heart fills immediately, the toast shows the sync settling */
function toggleHeart() {
  if (saved()) {
    const prev = lists.filter((l) => l.on).map((l) => l.id);
    lists.forEach((l) => { l.on = false; });
    paint(); burst(false);
    const names = prev.map((id) => lists.find((l) => l.id === id).name);
    say('<span>Removed from <b>' + esc(names.length > 1 ? names.length + ' lists' : names[0]) + '</b></span>', { label: 'Undo', run: () => { prev.forEach((id) => { lists.find((l) => l.id === id).on = true; }); paint(); burst(true); say('<span>Restored to <b>' + esc(names.length > 1 ? names.length + ' lists' : names[0]) + '</b></span>'); heart.focus(); } });
  } else {
    lists[0].on = true;
    paint(); burst(true);
    say('<i class="mco-heart-dot" aria-hidden="true"></i><span>Saving…</span>', null, true);
    setTimeout(() => {
      if (!root.isConnected || !lists[0].on) return;
      say('<span>Saved to <b>' + esc(lists[0].name) + '</b></span>', { label: 'Change', run: () => openMenu(heart) });
    }, 450);
  }
}

/* ---------- menu ---------- */
const items = () => Array.from(menu.querySelectorAll('.mco-heart-mi:not([hidden])'));
function openMenu(from) {
  opener = from || listsBtn;
  newForm.hidden = true; newBtn.hidden = false; newErr.textContent = '';
  menu.hidden = false;
  listsBtn.setAttribute('aria-expanded', 'true');
  clearTimeout(toastT); hideToast();
  const first = items().find((b) => b.getAttribute('aria-checked') === 'true') || items()[0];
  first.focus();
}
function closeMenu(refocus) {
  if (menu.hidden) return;
  menu.hidden = true;
  listsBtn.setAttribute('aria-expanded', 'false');
  if (refocus && opener) opener.focus();
}
function toggleList(id) {
  const l = lists.find((x) => x.id === id);
  const was = saved();
  l.on = !l.on;
  paint();
  if (saved() !== was) burst(saved());
  const b = mlist.querySelector('[data-l="' + id + '"]');
  if (b) b.focus();
}

heart.addEventListener('click', () => { closeMenu(false); toggleHeart(); });
listsBtn.addEventListener('click', () => { menu.hidden ? openMenu(listsBtn) : closeMenu(true); });
menu.addEventListener('click', (e) => {
  const mi = e.target.closest('[data-l]');
  if (mi) {
    if (mi.getAttribute('aria-disabled') === 'true') { mi.querySelector('.mco-heart-lc').animate([{ translate: '0 0' }, { translate: '-3px 0' }, { translate: '3px 0' }, { translate: '0 0' }], { duration: 260 }); return; }
    toggleList(mi.dataset.l);
    return;
  }
  if (e.target.closest('[data-new]')) { newBtn.hidden = true; newForm.hidden = false; newName.value = ''; newName.removeAttribute('aria-invalid'); newErr.textContent = ''; newName.focus(); }
});
newForm.addEventListener('submit', (e) => {
  e.preventDefault();
  const name = newName.value.trim().replace(/\s+/g, ' ');
  const bad = !name ? 'Give the list a name.' : lists.some((l) => l.name.toLowerCase() === name.toLowerCase()) ? 'You already have a list called “' + name + '”.' : '';
  if (bad) { newName.setAttribute('aria-invalid', 'true'); newErr.textContent = bad; newName.focus(); return; }
  const was = saved();
  lists.push({ id: 'l' + Date.now().toString(36), name, n: 0, on: true });
  newForm.hidden = true; newBtn.hidden = false;
  paint();
  if (!was) burst(true);
  mlist.lastElementChild.focus();
});
newName.addEventListener('input', () => { newName.removeAttribute('aria-invalid'); newErr.textContent = ''; });

root.addEventListener('keydown', (e) => {
  if (menu.hidden) return;
  if (e.key === 'Escape') {
    e.preventDefault();
    if (!newForm.hidden) { newForm.hidden = true; newBtn.hidden = false; newBtn.focus(); return; }
    closeMenu(true); return;
  }
  if (e.target === newName) return;
  const its = items(), i = its.indexOf(document.activeElement);
  const n = { ArrowDown: i + 1, ArrowUp: i - 1, Home: 0, End: its.length - 1 }[e.key];
  if (n !== undefined) { e.preventDefault(); its[(n + its.length) % its.length].focus(); }
  if (e.key === 'Tab') closeMenu(false);
});
root.addEventListener('pointerdown', (e) => { if (!menu.hidden && !menu.contains(e.target) && !listsBtn.contains(e.target)) closeMenu(false); });
toast.addEventListener('pointerleave', () => { if (toast.innerHTML) arm(); });

renderOdo(BASE_SAVES, false);
paint();

css:
@property --mco-fbt-sweep { syntax: "<angle>"; inherits: false; initial-value: 0deg; }
@property --mco-fbt-fill { syntax: "<number>"; inherits: true; initial-value: 0; }
@keyframes mco-fbt-sweep { from { --mco-fbt-sweep: 0deg; } to { --mco-fbt-sweep: 360deg; } }
@keyframes mco-fbt-spin { to { rotate: 360deg; } }
@keyframes mco-fbt-pop { 0% { scale: .6; opacity: 0; } 100% { scale: 1; opacity: 1; } }

.mco-fbt {
  /* re-theme with these four */
  --mco-fbt-bg: oklch(0.235 0.022 128);
  --mco-fbt-ink: oklch(0.95 0.02 110);
  --mco-fbt-accent: oklch(0.89 0.16 118);
  --mco-fbt-warn: oklch(0.8 0.12 70);

  --mco-fbt-muted: color-mix(in oklch, var(--mco-fbt-ink) 58%, var(--mco-fbt-bg));
  --mco-fbt-faint: color-mix(in oklch, var(--mco-fbt-ink) 30%, var(--mco-fbt-bg));
  --mco-fbt-line: color-mix(in oklch, var(--mco-fbt-ink) 11%, transparent);
  --mco-fbt-raise: color-mix(in oklch, var(--mco-fbt-ink) 5%, transparent);
  --mco-fbt-tint: color-mix(in oklch, var(--mco-fbt-accent) 14%, transparent);
  --mco-fbt-out: cubic-bezier(.2, .9, .25, 1);
  --mco-fbt-spring: linear(0, 0.009, 0.035 2.1%, 0.141 4.4%, 0.723 12.9%, 0.938 16.7%, 1.017 19.4%, 1.077 22.4%, 1.101 25.5%, 1.096 28.9%, 1.065 34.1%, 1.016 42.2%, 0.997 49.1%, 0.991 56.4%, 1.001 76.4%, 1);

  container-type: inline-size;
  position: relative; box-sizing: border-box; width: 100%; min-height: 158px;
  display: grid; gap: 14px; align-content: start; padding: 16px;
  border-radius: 18px; border: 1px solid var(--mco-fbt-line);
  background: radial-gradient(110% 60% at 0% 100%, color-mix(in oklch, var(--mco-fbt-accent) 7%, transparent), transparent 70%), var(--mco-fbt-bg);
  color: var(--mco-fbt-ink); accent-color: var(--mco-fbt-accent);
  font: 400 13px/1.4 system-ui, -apple-system, "Segoe UI", sans-serif;
  -webkit-font-smoothing: antialiased;

  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(button, select) { font: inherit; color: inherit; margin: 0; }
  & :where(button) { background: none; border: 0; padding: 0; cursor: pointer; }
  & :where(p, h3) { margin: 0; }
  & :where(svg) { display: block; flex: none; fill: none; stroke: currentColor; stroke-width: 1.5; stroke-linecap: round; stroke-linejoin: round; }
  & :focus-visible { outline: 2px solid var(--mco-fbt-accent); outline-offset: 2px; }
  & .mco-fbt-sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }

  & .mco-fbt-eyebrow { font-size: 10.5px; font-weight: 700; letter-spacing: .12em; text-transform: uppercase; color: var(--mco-fbt-accent); }
  & .mco-fbt-title { margin-top: 2px; font-size: clamp(17px, 5.6cqi, 20px); font-weight: 720; letter-spacing: -.02em; text-wrap: balance; }

  /* ---------- the equation: rows share one column grid through subgrid, so prices align ---------- */
  & .mco-fbt-items { display: grid; grid-template-columns: 22px 44px minmax(0, 1fr) auto; column-gap: 12px; }
  & .mco-fbt-row {
    grid-column: 1 / -1; display: grid; grid-template-columns: subgrid; align-items: center;
    position: relative; isolation: isolate; padding-block: 8px; cursor: pointer;
    &::before { content: ""; position: absolute; inset: 0 -8px; z-index: -1; border-radius: 12px; pointer-events: none; transition: background-color .2s; }
    &:hover::before { background: var(--mco-fbt-raise); }
  }
  & .mco-fbt-cb { width: 18px; height: 18px; margin: 0 0 0 2px; cursor: pointer; justify-self: center; }
  & .mco-fbt-art {
    display: grid; place-items: center; width: 44px; height: 44px; border-radius: 11px;
    background: linear-gradient(160deg, color-mix(in oklch, var(--mco-fbt-accent) 22%, var(--mco-fbt-bg)), color-mix(in oklch, var(--mco-fbt-ink) 6%, var(--mco-fbt-bg)));
    color: var(--mco-fbt-accent); box-shadow: inset 0 0 0 1px var(--mco-fbt-line);
    transition: filter .35s, opacity .35s, scale .45s var(--mco-fbt-spring), rotate .45s var(--mco-fbt-spring);
    & svg { width: 26px; height: 26px; stroke-width: 1.4; }
  }
  & .mco-fbt-row:hover .mco-fbt-art { rotate: -4deg; scale: 1.05; }
  & .mco-fbt-name {
    display: grid; justify-items: start; gap: 2px; min-width: 0; font-size: 13px; font-weight: 620; line-height: 1.25; text-wrap: balance;
    & small { font-size: 11.5px; font-weight: 450; color: var(--mco-fbt-muted); }
    transition: color .3s;
  }
  & .mco-fbt-size {
    position: relative; display: inline-grid;
    & select {
      appearance: none; -webkit-appearance: none; height: 24px; padding: 0 22px 0 8px; border-radius: 7px; border: 0;
      background: var(--mco-fbt-raise); box-shadow: inset 0 0 0 1px var(--mco-fbt-line); font-size: 11.5px; font-weight: 600; cursor: pointer;
      color: var(--mco-fbt-ink);
    }
    & select option { color: oklch(0.2 0.02 128); background: oklch(0.97 0.01 110); }
    &::after { content: ""; position: absolute; right: 8px; top: 50%; width: 6px; height: 6px; margin-top: -5px; border: solid var(--mco-fbt-muted); border-width: 0 1.5px 1.5px 0; rotate: 45deg; pointer-events: none; }
  }
  & .mco-fbt-price {
    justify-self: end; text-align: right; font: 600 13px/1.2 ui-monospace, Menlo, monospace; font-variant-numeric: tabular-nums;
    background: linear-gradient(currentColor, currentColor) 0 55% / 0 1.5px no-repeat; transition: background-size .35s var(--mco-fbt-out), color .3s;
  }
  & .mco-fbt-op {
    grid-column: 1; justify-self: center; display: grid; place-items: center; width: 18px; height: 18px; margin: -6px 0; position: relative; z-index: 1;
    border-radius: 50%; background: var(--mco-fbt-bg); box-shadow: inset 0 0 0 1px var(--mco-fbt-line); color: var(--mco-fbt-muted);
    transition: opacity .3s, scale .4s var(--mco-fbt-spring), rotate .4s var(--mco-fbt-spring);
    & svg { width: 12px; height: 12px; stroke-width: 1.8; }
  }
  /* unchecked rows step back: art greys, price strikes, the operator after it turns into a minus */
  & .mco-fbt-row:has(.mco-fbt-cb:not(:checked)) {
    & .mco-fbt-art { filter: grayscale(1); opacity: .45; scale: .9; }
    & .mco-fbt-name { color: var(--mco-fbt-muted); }
    & .mco-fbt-price { color: var(--mco-fbt-faint); background-size: 100% 1.5px; }
  }
  & .mco-fbt-row:has(.mco-fbt-cb:not(:checked)) + .mco-fbt-op, & .mco-fbt-op:has(+ .mco-fbt-row .mco-fbt-cb:not(:checked)) { opacity: .45; scale: .85; rotate: 45deg; }

  /* ---------- unlock meter ---------- */
  & .mco-fbt-meter { display: grid; gap: 6px; }
  & .mco-fbt-seg {
    display: grid; grid-template-columns: repeat(3, 1fr); gap: 4px;
    & i { height: 5px; border-radius: 3px; background: var(--mco-fbt-line); position: relative; overflow: hidden; }
    & i::after { content: ""; position: absolute; inset: 0; border-radius: inherit; background: var(--mco-fbt-accent); transform-origin: left; scale: 0 1; transition: scale .5s var(--mco-fbt-out); }
    & i:nth-child(1)::after { scale: clamp(0, var(--mco-fbt-fill), 1) 1; }
    & i:nth-child(2)::after { scale: clamp(0, calc(var(--mco-fbt-fill) - 1), 1) 1; transition-delay: 60ms; }
    & i:nth-child(3)::after { scale: clamp(0, calc(var(--mco-fbt-fill) - 2), 1) 1; transition-delay: 120ms; }
  }
  & .mco-fbt-hint { font-size: 12px; color: var(--mco-fbt-muted); text-wrap: pretty;
    & b { color: var(--mco-fbt-ink); font-weight: 650; }
  }
  & .mco-fbt-meter[data-on] .mco-fbt-hint { color: var(--mco-fbt-accent); font-weight: 600; }

  /* ---------- totals; on unlock a conic border sweeps once around the panel ---------- */
  & .mco-fbt-sum {
    position: relative; display: grid; padding: 10px 12px; border-radius: 13px; background: var(--mco-fbt-raise); isolation: isolate;
    &::before {
      content: ""; position: absolute; inset: 0; border-radius: inherit; padding: 1.5px; z-index: -1;
      background: conic-gradient(from var(--mco-fbt-sweep), transparent 0 70%, var(--mco-fbt-accent) 88%, transparent 100%), var(--mco-fbt-line);
      -webkit-mask: linear-gradient(#000 0 0) content-box exclude, linear-gradient(#000 0 0); mask: linear-gradient(#000 0 0) content-box exclude, linear-gradient(#000 0 0);
      opacity: 1;
