  }
  & .mco-fbt-save {
    display: grid; grid-template-columns: 1fr auto; overflow: hidden; font-size: 12.5px; color: var(--mco-fbt-accent);
    max-height: 0; opacity: 0; transition: max-height .4s var(--mco-fbt-out), opacity .3s, margin .4s var(--mco-fbt-out);
    & span:last-child { font: 650 12.5px/1.4 ui-monospace, Menlo, monospace; font-variant-numeric: tabular-nums; }
  }
  & .mco-fbt-sum[data-on] .mco-fbt-save { max-height: 24px; opacity: 1; margin-bottom: 4px; }
  & .mco-fbt-total {
    display: flex; align-items: baseline; justify-content: space-between; gap: 10px;
    & > span:first-child { font-size: 13px; font-weight: 650; }
    & small { font-size: 11.5px; font-weight: 450; color: var(--mco-fbt-muted); }
  }
  & .mco-fbt-tval {
    display: inline-flex; align-items: baseline; gap: 8px; font-family: ui-monospace, Menlo, monospace; font-variant-numeric: tabular-nums;
