    & s:empty { display: none; }
    & b { font-size: clamp(18px, 6.4cqi, 22px); font-weight: 700; letter-spacing: -.03em; }
    & b.is-bump { animation: mco-fbt-pop .4s var(--mco-fbt-spring); }
  }

  & .mco-fbt-cta {
