    &:hover:not(:disabled) { background: color-mix(in oklch, var(--mco-fbt-accent) 88%, white); }
    &:active:not(:disabled) { scale: .98; }
    &:disabled { background: var(--mco-fbt-raise); color: var(--mco-fbt-faint); cursor: not-allowed; box-shadow: inset 0 0 0 1px var(--mco-fbt-line); }
    &[aria-busy="true"] { cursor: progress;
      & span { opacity: 0; }
      &::after { content: ""; position: absolute; inset: 0; margin: auto; width: 16px; height: 16px; border-radius: 50%; border: 2px solid color-mix(in oklch, var(--mco-fbt-bg) 25%, transparent); border-top-color: var(--mco-fbt-bg); animation: mco-fbt-spin .7s linear infinite; }
    }
    &[data-done], &[data-done]:hover:not(:disabled) { background: var(--mco-fbt-ink); }
    & svg { width: 16px; height: 16px; stroke-width: 2.2; animation: mco-fbt-pop .4s var(--mco-fbt-spring) both; }
  }

  @container (max-width: 290px) {
    & .mco-fbt-items { grid-template-columns: 20px 38px minmax(0, 1fr) auto; column-gap: 9px; }
    & .mco-fbt-art { width: 38px; height: 38px; & svg { width: 22px; height: 22px; } }
    & .mco-fbt-price { font-size: 12px; }
  }
}

@media (prefers-reduced-motion: reduce) {
  .mco-fbt {
    & .mco-fbt-art, & .mco-fbt-op, & .mco-fbt-price, & .mco-fbt-seg i::after, & .mco-fbt-save { transition-duration: .01s; transition-delay: 0s; }
    & .mco-fbt-row:hover .mco-fbt-art { rotate: none; scale: none; }
    & .mco-fbt-sum.is-unlock::before, & .mco-fbt-tval b.is-bump, & .mco-fbt-cta svg { animation: none; }
    & .mco-fbt-cta[aria-busy="true"]::after { animation-duration: 2s; }
  }
}

