const $ = (s, el) => (el || root).querySelector(s);
const RM = matchMedia('(prefers-reduced-motion: reduce)');
const ITEMS = { pack: { name: 'Trailhead 28L Daypack', price: 11900 }, shell: { name: 'Packable Rain Shell', price: 8900 }, socks: { name: 'Merino Trail Socks', price: 2400 } };
const PCT = 15;
const eur = (c) => '€' + (c / 100).toFixed(2);
const rows = Array.from(root.querySelectorAll('.mco-fbt-row'));
const meter = $('[data-meter]'), sum = $('[data-sum]'), cta = $('[data-cta]'), totalEl = $('[data-total]');
let wasOn = null, lastTotal = null, added = false;

function state() {
  const on = rows.filter((r) => $('.mco-fbt-cb', r).checked).map((r) => r.dataset.k);
  const gross = on.reduce((a, k) => a + ITEMS[k].price, 0);
  const all = on.length === rows.length;
  const save = all ? Math.round((ITEMS.shell.price + ITEMS.socks.price) * PCT / 100) : 0;
  return { on, gross, save, total: gross - save, all };
}

function paint(user) {
  const s = state();
  root.style.setProperty('--mco-fbt-fill', s.on.length);
  meter.toggleAttribute('data-on', s.all);
  sum.toggleAttribute('data-on', s.all);
  const missing = rows.filter((r) => !$('.mco-fbt-cb', r).checked).map((r) => ITEMS[r.dataset.k].name);
  const potential = Math.round((ITEMS.shell.price + ITEMS.socks.price) * PCT / 100);
  $('[data-hint]').innerHTML = s.all ? 'Bundle unlocked — ' + PCT + '% off the add-ons' :
    'Add <b></b> to save ' + eur(potential);
  if (!s.all) $('[data-hint] b').textContent = missing.length === 1 ? missing[0] : missing.length + ' more items';
  $('[data-save]').textContent = '−' + eur(s.save || potential);
  $('[data-count]').textContent = 'for ' + s.on.length + (s.on.length === 1 ? ' item' : ' items');
  $('[data-was]').textContent = s.save ? eur(s.gross) : '';
  totalEl.textContent = eur(s.total);
  if (lastTotal !== null && lastTotal !== s.total && !RM.matches) { totalEl.classList.remove('is-bump'); void totalEl.offsetWidth; totalEl.classList.add('is-bump'); }
  lastTotal = s.total;
  if (user && s.all && wasOn === false && !RM.matches) { sum.classList.remove('is-unlock'); void sum.offsetWidth; sum.classList.add('is-unlock'); }
  wasOn = s.all;
  if (added) { added = false; cta.removeAttribute('data-done'); cta.innerHTML = '<span data-ctatxt></span>'; }
  cta.disabled = s.on.length === 0;
  $('[data-ctatxt]').textContent = s.on.length === 0 ? 'Select at least one item' : s.all ? 'Add all 3 to bag' : s.on.length === 1 ? 'Add 1 item to bag' : 'Add ' + s.on.length + ' items to bag';
  cta.dataset.n = s.on.length;
}

root.addEventListener('change', (e) => { if (e.target.matches('.mco-fbt-cb')) paint(true); });
root.addEventListener('click', (e) => {
  /* the whole row toggles, apart from the checkbox itself and the size menu */
  const row = e.target.closest('.mco-fbt-row');
  if (row && !e.target.closest('input, select, label')) { const cb = $('.mco-fbt-cb', row); cb.checked = !cb.checked; paint(true); }
});
$('[data-size]').addEventListener('change', (e) => {
  const cb = $('.mco-fbt-row[data-k="shell"] .mco-fbt-cb');
  cb.setAttribute('aria-label', 'Include Packable Rain Shell, size ' + e.target.value + ', €89.00');
  if (!cb.checked) { cb.checked = true; paint(true); }
});

cta.addEventListener('click', () => {
  if (cta.disabled || cta.getAttribute('aria-busy') === 'true' || cta.hasAttribute('data-done')) return;
  const s = state();
  cta.setAttribute('aria-busy', 'true');
  setTimeout(() => {
    if (!root.isConnected) return;
    cta.removeAttribute('aria-busy');
    cta.setAttribute('data-done', '');
    added = true;
    cta.innerHTML = '<svg viewBox="0 0 16 16" aria-hidden="true"><path d="M3.5 8.5l3 3 6-7"/></svg><span data-ctatxt></span>';
    $('[data-ctatxt]').textContent = s.on.length + (s.on.length === 1 ? ' item' : ' items') + ' added · ' + eur(s.total);
  }, 750);
});
paint(false);

