@property --mco-split-n { syntax: "<number>"; inherits: true; initial-value: 4; }
@property --mco-split-today { syntax: "<number>"; inherits: true; initial-value: 1; }
@keyframes mco-split-spin { to { rotate: 360deg; } }
@keyframes mco-split-draw { from { stroke-dashoffset: var(--len); } }

.mco-split {
  /* re-theme with these four */
  --mco-split-bg: oklch(0.2 0.035 12);
  --mco-split-ink: oklch(0.95 0.015 40);
  --mco-split-accent: oklch(0.82 0.11 52);
  --mco-split-ok: oklch(0.84 0.1 165);

  --mco-split-muted: color-mix(in oklch, var(--mco-split-ink) 58%, var(--mco-split-bg));
  --mco-split-faint: color-mix(in oklch, var(--mco-split-ink) 30%, var(--mco-split-bg));
  --mco-split-line: color-mix(in oklch, var(--mco-split-ink) 11%, transparent);
  --mco-split-raise: color-mix(in oklch, var(--mco-split-ink) 5%, transparent);
  --mco-split-out: cubic-bezier(.2, .9, .25, 1);
  --mco-split-spring: linear(0, 0.009, 0.035 2.1%, 0.141 4.4%, 0.723 12.9%, 0.938 16.7%, 1.017 19.4%, 1.077 22.4%, 1.101 25.5%, 1.096 28.9%, 1.065 34.1%, 1.016 42.2%, 0.997 49.1%, 0.991 56.4%, 1.001 76.4%, 1);
  --mco-split-mono: ui-monospace, Menlo, "SF Mono", Consolas, monospace;

  container-type: inline-size;
  position: relative; box-sizing: border-box; width: 100%; min-height: 158px;
  display: grid; gap: 14px; align-content: start; padding: 16px;
  border-radius: 18px; border: 1px solid var(--mco-split-line);
  background: radial-gradient(100% 60% at 100% 0%, color-mix(in oklch, var(--mco-split-accent) 10%, transparent), transparent 65%), var(--mco-split-bg);
  color: var(--mco-split-ink);
  font: 400 13px/1.4 system-ui, -apple-system, "Segoe UI", sans-serif;
  -webkit-font-smoothing: antialiased;

  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(button) { font: inherit; color: inherit; background: none; border: 0; padding: 0; margin: 0; cursor: pointer; }
  & :where(p, h3, dl, dd, ol) { margin: 0; }
  & :where(svg) { display: block; flex: none; fill: none; stroke: currentColor; stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; }
  & :focus-visible { outline: 2px solid var(--mco-split-accent); outline-offset: 2px; }

  & .mco-split-eyebrow { font-size: 10.5px; font-weight: 700; letter-spacing: .12em; text-transform: uppercase; color: var(--mco-split-accent); }
  & .mco-split-title {
    display: flex; flex-wrap: wrap; align-items: baseline; justify-content: space-between; gap: 2px 10px; margin-top: 2px;
    font-size: clamp(15px, 5cqi, 18px); font-weight: 680; letter-spacing: -.012em; text-wrap: balance;
    & span { font: 600 13px/1 var(--mco-split-mono); color: var(--mco-split-muted); font-variant-numeric: tabular-nums; }
  }

  /* ---------- plan chips: one scroll-snapping row ---------- */
  & .mco-split-plans {
    display: grid; grid-auto-flow: column; grid-auto-columns: max-content; gap: 6px; overflow-x: auto; scroll-snap-type: x mandatory; scrollbar-width: none;
    margin: 0 -16px; padding: 2px 16px;
    -webkit-mask: linear-gradient(to right, transparent, #000 16px, #000 calc(100% - 24px), transparent); mask: linear-gradient(to right, transparent, #000 16px, #000 calc(100% - 24px), transparent);
    &::-webkit-scrollbar { display: none; }
  }
  & .mco-split-plan {
    scroll-snap-align: start; scroll-margin-inline: 16px; display: grid; gap: 1px; padding: 8px 12px; border-radius: 11px; text-align: left;
    box-shadow: inset 0 0 0 1px var(--mco-split-line); transition: background-color .2s, box-shadow .2s, color .2s;
    & b { font-size: 12.5px; font-weight: 650; white-space: nowrap; }
    & span { font-size: 11px; color: var(--mco-split-muted); white-space: nowrap; }
    &:hover:not([aria-disabled="true"]) { background: var(--mco-split-raise); }
    &:focus-visible { outline-offset: -2px; }
    &[aria-checked="true"] { background: var(--mco-split-accent); color: var(--mco-split-bg); box-shadow: none;
      & span { color: color-mix(in oklch, var(--mco-split-bg) 70%, var(--mco-split-accent)); }
    }
    &[aria-disabled="true"] { cursor: not-allowed; color: var(--mco-split-faint); box-shadow: inset 0 0 0 1px var(--mco-split-line); background: repeating-linear-gradient(135deg, transparent 0 5px, var(--mco-split-raise) 5px 6px);
      & span { color: var(--mco-split-faint); }
    }
  }

  /* ---------- ring: --mco-split-n is a registered number, so the segments re-divide continuously ---------- */
  & .mco-split-main { display: grid; grid-template-columns: auto minmax(0, 1fr); gap: 16px; align-items: center; }
  & .mco-split-ring {
    --g: 5deg; --seg: calc(360deg / var(--mco-split-n));
    position: relative; width: clamp(104px, 34cqi, 124px); aspect-ratio: 1; border-radius: 50%; display: grid; place-items: center;
    transition: --mco-split-n .9s cubic-bezier(.3, .9, .2, 1), --mco-split-today .4s;
    &::before, &::after {
      content: ""; position: absolute; inset: 0; border-radius: 50%;
      -webkit-mask: radial-gradient(farthest-side, transparent calc(100% - 11px), #000 calc(100% - 10.5px)); mask: radial-gradient(farthest-side, transparent calc(100% - 11px), #000 calc(100% - 10.5px));
    }
    &::before { background: repeating-conic-gradient(from calc(var(--g) / 2), var(--mco-split-faint) 0 calc(var(--seg) - var(--g)), transparent 0 var(--seg)); }
    &::after {
      background: conic-gradient(from calc(var(--g) / 2), var(--mco-split-accent) 0 calc(var(--seg) - var(--g)), transparent 0);
      opacity: var(--mco-split-today);
      filter: drop-shadow(0 0 6px color-mix(in oklch, var(--mco-split-accent) 60%, transparent));
    }
  }
  & .mco-split-center {
    display: grid; justify-items: center; text-align: center; line-height: 1.1;
    & b { font: 700 clamp(16px, 5.4cqi, 19px)/1.1 var(--mco-split-mono); letter-spacing: -.04em; font-variant-numeric: tabular-nums; }
    & span { margin-top: 3px; font-size: 10.5px; color: var(--mco-split-muted); }
  }
  & .mco-split-facts {
    display: grid; gap: 7px; min-width: 0;
    & div { display: flex; align-items: baseline; justify-content: space-between; gap: 8px; }
    & dt { font-size: 12px; color: var(--mco-split-muted); white-space: nowrap; }
    & dd { font: 600 12.5px/1.2 var(--mco-split-mono); font-variant-numeric: tabular-nums; text-align: right; }
    & .mco-split-tot { padding-top: 7px; border-top: 1px solid var(--mco-split-line);
      & dt { color: var(--mco-split-ink); font-weight: 650; }
      & dd { font-size: 14px; font-weight: 700; }
    }
    & dd[data-hi] { color: var(--mco-split-accent); }
  }

  /* ---------- schedule ---------- */
  & .mco-split-sched { display: grid; gap: 6px; }
  & .mco-split-sh {
    display: flex; justify-content: space-between; align-items: baseline; gap: 10px; font-size: 11px; color: var(--mco-split-muted);
    & span:first-child { font-weight: 700; letter-spacing: .1em; text-transform: uppercase; color: var(--mco-split-ink); }
    & span:last-child { text-align: right; text-wrap: balance; }
  }
  & .mco-split-list {
    list-style: none; padding: 0 4px 0 0; display: grid; max-height: 132px; overflow-y: auto; overscroll-behavior: contain;
    scrollbar-width: thin; scrollbar-color: var(--mco-split-line) transparent; border-radius: 8px;
    &:focus-visible { outline-offset: 2px; }
  }
  & .mco-split-li {
    position: relative; display: grid; grid-template-columns: 14px minmax(0, 1fr) auto; align-items: center; gap: 10px; min-height: 33px;
    border-bottom: 1px solid var(--mco-split-line); font-variant-numeric: tabular-nums;
    &:last-child { border-bottom: 0; }
    & i { width: 9px; height: 9px; border-radius: 50%; justify-self: center; box-shadow: inset 0 0 0 1.5px var(--mco-split-faint); }
    & span { font-size: 12.5px; }
    & small { color: var(--mco-split-muted); font-size: 11.5px; }
    & b { font: 600 12.5px/1 var(--mco-split-mono); }
    &[data-now] i { background: var(--mco-split-accent); box-shadow: 0 0 0 3px color-mix(in oklch, var(--mco-split-accent) 25%, transparent); }
    &[data-now] span { font-weight: 650; }
    &.is-new { transition: opacity .35s var(--mco-split-out), translate .45s var(--mco-split-out); transition-delay: calc(var(--i) * 32ms);
      @starting-style { opacity: 0; translate: 0 6px; } }
  }

  /* ---------- action ---------- */
  & .mco-split-foot { display: grid; gap: 6px; &[hidden] { display: none; } }
  & .mco-split-go {
    position: relative; height: 44px; border-radius: 12px; background: var(--mco-split-ink); color: var(--mco-split-bg); font-size: 13.5px; font-weight: 680;
    transition: background-color .2s, scale .2s;
    &:hover:not([aria-busy="true"]) { background: var(--mco-split-accent); }
    &:active { scale: .98; }
    &[aria-busy="true"] { cursor: progress;
      & span { opacity: .0; }
      &::after { content: ""; position: absolute; inset: 0; margin: auto; width: 16px; height: 16px; border-radius: 50%; border: 2px solid color-mix(in oklch, var(--mco-split-bg) 25%, transparent); border-top-color: var(--mco-split-bg); animation: mco-split-spin .7s linear infinite; }
    }
  }
  & .mco-split-fine { font-size: 11px; color: var(--mco-split-muted); text-align: center; text-wrap: balance; }
  & .mco-split-ok {
    display: grid; grid-template-columns: auto minmax(0, 1fr) auto; align-items: center; gap: 12px; padding: 10px 12px; border-radius: 13px;
    background: color-mix(in oklch, var(--mco-split-ok) 12%, transparent); box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--mco-split-ok) 35%, transparent);
    transition: opacity .3s, translate .45s var(--mco-split-spring);
    @starting-style { opacity: 0; translate: 0 8px; }
    &[hidden] { display: none; }
    & svg { width: 32px; height: 32px; color: var(--mco-split-ok); stroke-width: 2.4; }
    & circle { --len: 101; stroke-dasharray: 101; animation: mco-split-draw .6s var(--mco-split-out) backwards; }
    & path { --len: 24; stroke-dasharray: 24; animation: mco-split-draw .35s .35s var(--mco-split-out) backwards; }
    & .mco-split-okt { font-weight: 680; font-size: 13.5px; }
    & .mco-split-oks { font-size: 12px; color: var(--mco-split-muted); text-wrap: pretty; }
    & button { height: 30px; padding: 0 11px; border-radius: 9px; font-size: 12px; font-weight: 650; box-shadow: inset 0 0 0 1px var(--mco-split-line); }
    & button:hover { background: var(--mco-split-raise); }
  }

  @container (max-width: 270px) {
    & .mco-split-main { gap: 12px; }
    & .mco-split-ring { width: 92px; &::before, &::after { -webkit-mask: radial-gradient(farthest-side, transparent calc(100% - 9px), #000 calc(100% - 8.5px)); mask: radial-gradient(farthest-side, transparent calc(100% - 9px), #000 calc(100% - 8.5px)); } }
    & .mco-split-center b { font-size: 14.5px; }
    & .mco-split-facts dt { font-size: 11.5px; }
    & .mco-split-facts dd { font-size: 12px; }
    & .mco-split-list { max-height: 100px; }
    & .mco-split-sh span:last-child { display: none; }
  }
  @container (max-width: 220px) {
    & .mco-split-main { grid-template-columns: minmax(0, 1fr); justify-items: center; }
    & .mco-split-facts { width: 100%; }
  }
}

@media (prefers-reduced-motion: reduce) {
  .mco-split {
    & .mco-split-ring { transition: none; }
    & .mco-split-li.is-new { transition: opacity .2s; transition-delay: 0s; @starting-style { opacity: 0; translate: none; } }
    & .mco-split-ok { transition: opacity .2s; @starting-style { opacity: 0; translate: none; } }
    & .mco-split-ok :is(circle, path) { animation: none; }
    & .mco-split-go[aria-busy="true"]::after { animation-duration: 2s; }
  }
}

