const btns = Array.from(plansEl.querySelectorAll('[role="radio"]'));
let cur = 'p4';

/* every figure is built from the cent-exact schedule, so the ring, facts and list agree */
function schedule(p) {
  const out = [], t0 = new Date(); t0.setHours(12, 0, 0, 0);
  const due = (i) => {
    const d = new Date(t0);
    if (p.every === 'w2') d.setDate(d.getDate() + 14 * i);
    else { const k = p.today ? i : i + 1, day = d.getDate(); d.setDate(1); d.setMonth(d.getMonth() + k); d.setDate(Math.min(day, new Date(d.getFullYear(), d.getMonth() + 1, 0).getDate())); }
    return d;
  };
  if (!p.rate) {
    const each = Math.floor(PRICE / p.n), rest = PRICE - each * p.n;
    for (let i = 0; i < p.n; i++) out.push({ d: due(i), amt: each + (i === 0 ? rest : 0) });
  } else {
    const r = p.rate / 12, pay = Math.round(PRICE * r / (1 - Math.pow(1 + r, -p.n)));
    let bal = PRICE;
    for (let i = 0; i < p.n; i++) {
      const int = Math.round(bal * r), amt = i === p.n - 1 ? bal + int : pay;
      bal = bal + int - amt;
      out.push({ d: due(i), amt });
    }
  }
  return out;
}

function render(animateList) {
  const p = PLANS[cur], s = schedule(p);
  const total = s.reduce((a, x) => a + x.amt, 0), interest = total - PRICE;
  const each = s[1].amt;
  ring.style.setProperty('--mco-split-n', p.n);
  ring.style.setProperty('--mco-split-today', p.today ? 1 : 0);
  $('[data-each]').textContent = eur(each);
  $('[data-times]').textContent = '× ' + p.n + ' payments';
  const today = $('[data-today]');
  today.textContent = p.today ? eur(s[0].amt) : '€0.00';
  today.toggleAttribute('data-hi', p.today);
  $('[data-interest]').textContent = eur(interest);
  $('[data-total]').textContent = eur(total);
  $('[data-apr]').textContent = p.rate
    ? (p.rate * 100).toFixed(1) + '% fixed · ' + ((Math.pow(1 + p.rate / 12, 12) - 1) * 100).toFixed(2) + '% APR representative'
    : 'No interest, no fees when paid on time';
  list.innerHTML = s.map((x, i) => {
    const now = p.today && i === 0;
    return '<li class="mco-split-li' + (animateList ? ' is-new' : '') + '" style="--i:' + i + '"' + (now ? ' data-now' : '') + '><i></i>' +
      '<span>' + (now ? 'Today' : 'Payment ' + (i + 1)) + ' <small>' + (now ? fD.format(x.d) : (x.d.getFullYear() !== new Date().getFullYear() ? fDY.format(x.d) : fD.format(x.d))) + '</small></span>' +
      '<b>' + eur(x.amt) + '</b></li>';
  }).join('');
  list.scrollTop = 0;
  $('[data-gotxt]').textContent = 'Continue with ' + p.name;
  $('[data-fine]').textContent = p.rate ? 'Credit subject to status. A soft check won’t affect your credit score.' : 'A soft check that won’t affect your credit score.';
}

function pick(b, focus) {
  if (go.getAttribute('aria-busy') === 'true') return;
  if (b.getAttribute('aria-disabled') === 'true') {
    $('[data-fine]').textContent = '24 months is available on orders of €1,000 or more.';
    return;
  }
  cur = b.dataset.p;
  btns.forEach((x) => { const on = x === b; x.setAttribute('aria-checked', String(on)); x.tabIndex = on ? 0 : -1; });
  if (focus) b.focus({ preventScroll: true });
  /* keep the chosen chip clear of the faded edges without scrolling the page */
  const r = b.getBoundingClientRect(), c = plansEl.getBoundingClientRect(), behavior = RM.matches ? 'auto' : 'smooth';
  if (r.left < c.left + 30) plansEl.scrollBy({ left: r.left - c.left - 30, behavior });
  else if (r.right > c.right - 30) plansEl.scrollBy({ left: r.right - c.right + 30, behavior });
  render(true);
}
plansEl.addEventListener('click', (e) => { const b = e.target.closest('[role="radio"]'); if (b) pick(b); });
plansEl.addEventListener('keydown', (e) => {
  const d = { ArrowRight: 1, ArrowDown: 1, ArrowLeft: -1, ArrowUp: -1 }[e.key];
  if (!d) return;
  e.preventDefault();
  const live = btns.filter((x) => x.getAttribute('aria-disabled') !== 'true');
  const i = live.indexOf(e.target.closest('[role="radio"]'));
  pick(live[(i + d + live.length) % live.length], true);
});

go.addEventListener('click', () => {
  if (go.getAttribute('aria-busy') === 'true') return;
  go.setAttribute('aria-busy', 'true');
  $('[data-fine]').textContent = 'Checking eligibility…';
  setTimeout(() => {
    if (!root.isConnected) return;
    go.removeAttribute('aria-busy');
    const p = PLANS[cur], s = schedule(p);
    $('[data-oks]').textContent = p.today ? 'First payment of ' + eur(s[0].amt) + ' today, then ' + (p.n - 1) + ' × ' + eur(s[1].amt) + ' ' + p.short + '.'
      : 'Nothing to pay today. First payment of ' + eur(s[0].amt) + ' on ' + fDY.format(s[0].d) + '.';
    foot.hidden = true;
    ok.hidden = false;
    $('[data-change]').focus();
  }, 900);
});
$('[data-change]').addEventListener('click', () => {
  ok.hidden = true;
  foot.hidden = false;
  render(false);
  plansEl.querySelector('[aria-checked="true"]').focus();
});

render(false);
